INSERT INTO `corpus_texts` (`book_id`, `pos`, `title`, `sid`, `text`, `translation`, `translation_src`) VALUES
  ('tangshi300', 1, '经鲁祭孔子而叹之', 'tangshi-ts-95', '夫子何为者栖栖一代中地犹鄹邑宅即鲁王宫叹凤嗟身否伤麟怨道穷今看两楹奠当与梦时同', '孔夫子是怎样的人呢，一生奔波忙碌、栖栖遑遑。他的出生地如今还是鄹邑，他的旧宅就是鲁王的宫殿。他曾叹息凤鸟不至、感伤自身不遇，又为麒麟被获而哀怨道之不行。如今看他受两楹之奠的祭祀，应当与他梦中的情景相同。', 'public-domain'),
  ('tangshi300', 2, '出塞', 'poems-xx4-04', '秦时明月汉时关万里长征人未还但使龙城飞将在不教胡马度阴山', '依旧是秦汉时的明月和边关，万里出征的将士还没有回还。只要龙城的飞将军还在，就不会让胡人的马匹越过阴山。', 'school'),
  ('tangshi300', 3, '江南曲', 'tangshi-ts-91', '嫁得瞿塘贾朝朝误妾期早知潮有信嫁与弄潮儿', '嫁给了一个瞿塘的商人，天天耽误我约定的归期。早知道潮水都有信用，不如嫁给那弄潮的少年。', 'public-domain'),
  ('tangshi300', 4, '从军行七首·其四', 'poems-xx5-14', '青海长云暗雪山孤城遥望玉门关黄沙百战穿金甲不破楼兰终不还', '青海湖上长云弥漫，遮暗了雪山，孤零零的城池远远望着玉门关。黄沙百战磨穿了身上的铠甲，不打败楼兰就绝不回还。', 'school'),
  ('tangshi300', 5, '蜀道难', 'tangshi-ts-74', '噫吁嚱危乎高哉蜀道之难难于上青天蚕丛及鱼凫开国何茫然尔来四万八千岁不与秦塞通人烟西当太白有鸟道可以横绝峨眉巅地崩山摧壮士死然后天梯石栈相钩连上有六龙回日之高标下有冲波逆折之回川黄鹤之飞尚不得过猿猱欲度愁攀援青泥何盘盘百步九折萦岩峦扪参历井仰胁息以手抚膺坐长叹问君西游何时还畏途巉岩不可攀但见悲鸟号古木雄飞雌从绕林间又闻子规啼夜月愁空山蜀道之难难于上青天使人听此凋朱颜连峰去天不盈尺枯松倒挂倚绝壁飞湍瀑流争喧豗砯崖转石万壑雷其险也如此嗟尔远道之人胡为乎来哉剑阁峥嵘而崔嵬一夫当关万夫莫开所守或匪亲化为狼与豺朝避猛虎夕避长蛇磨牙吮血杀人如麻锦城虽云乐不如早还家蜀道之难难于上青天侧身西望长咨嗟', '唉呀呀，多么危险多么高峻！蜀道的艰难，比上青天还难！蚕丛和鱼凫开国的年代多么遥远茫昧。从那时以来四万八千年，不与秦地互通人烟。西面对着太白山只有鸟飞的路径，可以横越峨眉山顶。山崩地裂壮士死去，然后才有天梯石栈互相钩连。上面有六龙驾日都要回旋的高峰，下面有波涛冲击、回旋倒流的河川。黄鹤高飞尚且飞不过去，猿猱想过也愁于攀援。青泥岭多么曲折，百步之内九次折转萦绕着山峦。手摸参星、身历井宿，仰头屏息，抚胸而坐、长声叹息。问你西游何时回来，可怕的道路、险峻的山岩不可攀登。只见悲鸟在古木上号叫，雄飞雌随绕在林间。又听见子规在月夜里啼叫，愁满空山。蜀道的艰难，比上青天还难，使人听了这消息都容颜憔悴。连绵的山峰离天不到一尺，枯松倒挂着倚在绝壁上。飞流瀑布争相喧腾，撞击山崖、转动巨石，万壑轰鸣如雷。它如此险要，可叹你这远道之人为什么到这里来呢。剑阁峥嵘而高峻，一人把关，万人也攻不开。守关的若不是亲信，就会变成豺狼。早上要躲避猛虎，晚上要躲避长蛇。它们磨牙吸血，杀人如麻。锦城虽说快乐，不如早些回家。蜀道的艰难，比上青天还难，侧身向西望去，长声叹息。', 'academic'),
  ('tangshi300', 6, '长信秋词·其三', 'tangshi-ts-321', '奉帚平明金殿开且将团扇共徘徊玉颜不及寒鸦色犹带昭阳日影来', '清晨拿起扫帚，金殿的门刚打开，暂且拿着团扇来回徘徊。
INSERT INTO `corpus_texts` (`book_id`, `pos`, `title`, `sid`, `text`, `translation`, `translation_src`) VALUES
  ('tangshi300', 43, '闻官军收河南河北', 'poems-xx5-16', '剑外忽传收蓟北初闻涕泪满衣裳却看妻子愁何在漫卷诗书喜欲狂白日放歌须纵酒青春作伴好还乡即从巴峡穿巫峡便下襄阳向洛阳', '在剑门关外忽然听说官军收复了蓟北，刚听到消息时眼泪沾满了衣裳。回头看妻子儿女的愁容不知哪里去了，随手卷起诗书欢喜得快要发狂。白天要放声高歌，痛饮美酒，趁着春光正好伴我返回故乡。即刻从巴峡穿过巫峡，再顺流而下经过襄阳直奔洛阳。', 'school'),
  ('tangshi300', 44, '登高', 'poems-gz10-05', '风急天高猿啸哀渚清沙白鸟飞回无边落木萧萧下不尽长江滚滚来万里悲秋常作客百年多病独登台艰难苦恨繁霜鬓潦倒新停浊酒杯', '风急天高，猿猴哀哀地啼叫；水清沙白，鸟儿在急风中盘旋。无边无际的树木萧萧地落下枯叶，望不到头的长江滚滚奔流而来。悲对秋景，感慨万里漂泊常年作客他乡，一生多病，今日独自登上高台。历尽了艰难苦恨，白发长满了双鬓，穷困潦倒，刚刚又停下了浇愁的酒杯。', 'academic'),
  ('tangshi300', 45, '别房太尉墓', 'tangshi-ts-117', '他乡复行役驻马别孤坟近泪无干土低空有断云对棋陪谢傅把剑觅徐君惟见林花落莺啼送客闻', '在他乡又要奔波远行，勒住马告别这孤零零的坟。走近坟前，泪水使地上的土没有一处是干的，低空飘着断开的云。当年我曾陪你对棋，如今像季札那样把剑挂在徐君墓树上。只见林中花落，莺啼送客声声入耳。', 'public-domain'),
  ('tangshi300', 46, '登楼', 'tangshi-ts-191', '花近高楼伤客心万方多难此登临锦江春色来天地玉垒浮云变古今北极朝廷终不改西山寇盗莫相侵可怜后主还祠庙日暮聊为梁甫吟', '繁花靠近高楼却伤了客子之心，万方多难时在此登临。锦江的春色来自天地之间，玉垒的浮云变幻着古今。北极星般的朝廷终究不会改变，西山的寇盗不要来侵扰。可怜那后主还留有祠庙，日暮时姑且吟起《梁甫吟》。', 'public-domain'),
  ('tangshi300', 47, '宿府', 'tangshi-ts-192', '清秋幕府井梧寒独宿江城蜡炬残永夜角声悲自语中天月色好谁看风尘荏苒音书绝关塞萧条行路难已忍伶俜十年事强移栖息一枝安', '清秋的幕府里井边梧桐生寒，独自宿在江城、蜡炬将要烧残。长夜的角声悲凉、仿佛自言自语，中天的月色虽好又有谁看。风尘荏苒、音书断绝，关塞萧条、行路艰难。已忍受伶俜漂泊十年的往事，勉强迁就栖息、求得一枝之安。', 'public-domain'),
  ('tangshi300', 48, '旅夜书怀', 'tangshi-ts-118', '细草微风岸危樯独夜舟星垂平野阔月涌大江流名岂文章著官应老病休飘飘何所似天地一沙鸥', '微风吹着岸边的细草，高耸的桅杆下夜里独泊着一只船。星星低垂、原野显得开阔，月亮涌起、大江奔流。名声岂是靠文章显著，官职应当因老病而罢休。飘泊不定像什么呢，像天地间一只沙鸥。', 'public-domain'),
  ('tangshi300', 49, '阁夜', 'tangshi-ts-193', '岁暮阴阳催短景天涯霜雪霁寒宵五更鼓角声悲壮三峡星河影动摇野哭千家闻战伐夷歌数处起渔樵卧龙跃马终黄土人事音书漫寂寥', '岁暮时日月催逼着短促的光阴，天涯的霜雪在寒夜放晴。五更的鼓角声悲壮，三峡的星河倒影摇动。野外的哭声千家里传来，是听到了战伐的消息；夷人的歌声几处响起，来自渔夫樵夫。卧龙诸葛亮与跃马的公孙述终究都成了黄土，人事与音书都徒然寂寥。', 'public-domain'),
  ('tangshi300', 50, '八阵图', 'tangshi-ts-233', '功盖三分国名成八阵图江流石不转遗恨失吞吴', '功业盖过三分的国家，名声成就于八阵图。江水奔流而阵石不移，遗恨的是失计于吞吴。', 'public-domain'),
  ('tangshi300', 51, '咏怀古迹·其一', 'tangshi-ts-194', '支离东北风尘际漂泊西南天地间三峡楼台淹日月五溪衣服共云山羯胡事主终无赖词客哀时且未还庾信平生最萧瑟暮年诗赋动江关', '我在东北风尘之中四处流离，漂泊在西南的天地之间。三峡的楼台淹留了岁月，五溪的衣装与云山共处。羯胡侍奉君主终究无赖，词人哀叹时世而未能归去。庾信平生最为萧瑟，暮年的诗赋却震动了江关。', 'public-domain'),
  ('tangshi300', 52, '咏怀古迹·其二', 'tangshi-ts-195', '摇落深知宋玉悲风流儒雅亦吾师怅望千秋一洒泪萧条异代不同时江山故宅空文藻云雨荒台岂梦思最是楚宫俱泯灭舟人指点到今疑', '草木摇落、我深知宋玉的悲凉，他的风流儒雅也是我的老师。怅望千秋、一同洒泪，萧条异代、不同时世。江山的故宅空留下文采，云雨的荒台岂是梦中的情思。最是那楚宫都已泯灭，船夫指点着至今还令人疑惑。', 'public-domain'),
  ('tangshi300', 53, '咏怀古迹·其三', 'tangshi-ts-196', '群山万壑赴荆门生长明妃尚有村一去紫台连朔漠独留青冢向黄昏画图省识春风面环佩空归夜月魂千载琵琶作胡语分明怨恨曲中论', '群山万壑奔赴荆门，王昭君生长的村庄至今还在。她一离开汉宫就远赴塞北沙漠，只留下一座青冢对着黄昏。凭图画哪里能认识她春风般的面容，环佩叮当、空自归来的只有夜月下的魂。千载以来琵琶弹着胡地的曲调，分明是怨恨在曲中诉说。', 'public-domain'),
  ('tangshi300', 54, '咏怀古迹·其四', 'tangshi-ts-197', '蜀主窥吴幸三峡崩年亦在永安宫翠华想像空山里玉殿虚无野寺中古庙杉松巢水鹤岁时伏腊走村翁武侯祠堂常邻近一体君臣祭祀同', '蜀主刘备窥视东吴、亲临三峡，驾崩之年也在永安宫。翠羽华盖只能在空山里想象，玉殿虚无、只存在于野寺之中。古庙的杉松上水鹤筑巢，逢年过节、村翁前来祭祀。武侯祠堂常常就在附近，君臣一体、祭祀也相同。', 'public-domain'),
  ('tangshi300', 55, '咏怀古迹·其五', 'tangshi-ts-198', '诸葛大名垂宇宙宗臣遗像肃清高三分割据纡筹策万古云霄一羽毛伯仲之间见伊吕指挥若定失萧曹运移汉祚终难复志决身歼军务劳', '诸葛亮的大名垂于宇宙，宗臣的遗像肃穆清高。三分割据、曲折地施展谋略，万古云霄中他如一片羽毛般高标。与伊尹吕尚相比也不相上下，指挥若定、使萧何曹参也失色。时运转移、汉朝的国祚终究难以恢复，志向坚定、以身殉国、军务劳瘁。', 'public-domain'),
  ('tangshi300', 56, '江南逢李龟年', 'poems-cz7-06', '岐王宅里寻常见崔九堂前几度闻正是江南好风景落花时节又逢君', '当年在岐王的府宅里常常看到你，在崔九的堂前也多次听过你的歌唱。如今正是江南风景最好的时候，在这落花的时节又遇到了你。', 'academic'),
  ('tangshi300', 57, '登岳阳楼', 'poems-gz10-21', '昔闻洞庭水今上岳阳楼吴楚东南坼乾坤日夜浮亲朋无一字老病有孤舟戎马关山北凭轩涕泗流', '从前就听说过洞庭湖的盛名，今天终于登上了岳阳楼。吴地和楚地被洞庭湖分割在东南两边，天地日月仿佛都日夜浮在湖中。亲戚朋友没有一封信来，年老多病只有一叶孤舟相伴。北方的关山又在燃起战火，我凭栏远望，涕泪横流。', 'academic'),
  ('tangshi300', 59, '谷口书斋寄杨补阙', 'tangshi-ts-143', '泉壑带茅茨云霞生薜帷竹怜新雨后山爱夕阳时闲鹭栖常早秋花落更迟家童扫萝径昨与故人期', '泉流山谷围绕着茅屋，云霞从薜荔的帷幕上升起。竹子在新雨后可爱，山在夕阳时最可爱。悠闲的白鹭归栖常早，秋花落得更迟。家童扫着藤萝小径，昨天已与故人相约。', 'public-domain'),
  ('tangshi300', 60, '送僧归日本', 'tangshi-ts-142', '上国随缘住来途若梦行浮天沧海远去世法舟轻水月通禅寂鱼龙听梵声惟怜一灯影万里眼中明', '你随缘在上国居住，来时的路途像梦一样。沧海浮天多么遥远，你离世乘坐的法舟轻快。水月通达禅寂之境，鱼龙也来听你诵经的声音。只怜那一盏孤灯的光影，在万里之外也照得眼中明亮。', 'public-domain'),
  ('tangshi300', 61, '赠阙下裴舍人', 'tangshi-ts-202', '二月黄鹂飞上林春城紫禁晓阴阴长乐钟声花外尽龙池柳色雨中深阳和不散穷途恨霄汉常悬捧日心献赋十年犹未遇羞将白发对华簪', '二月里黄鹂飞上林苑，春日的紫禁城清晨阴阴。长乐宫的钟声在花外消尽，龙池的柳色在雨中更深。和暖的阳气驱不散穷途的怨恨，云霄之中常悬着捧日之心。献赋十年仍未遇合，羞于带着白发去面对华簪。', 'public-domain'),
  ('tangshi300', 63, '贼退示官吏·并序', 'tangshi-ts-24', '癸卯岁西原贼入道州焚烧杀掠几尽而去明年贼又攻永破邵不犯此州边鄙而退岂力能制敌欤盖蒙其伤怜而已诸使何为忍苦征敛故作诗一篇以示官吏昔岁逢太平山林二十年泉源在庭户洞壑当门前井税有常期日晏犹得眠忽然遭世变数岁亲戎旃今来典斯郡山夷又纷然城小贼不屠人贫伤可怜是以陷邻境此州独见全使臣将王命岂不如贼焉今彼征敛者迫之如火煎谁能绝人命以作时世贤思欲委符节引竿自刺船将家就鱼麦归老江湖边', '癸卯年，西原的贼人攻入道州，烧杀抢掠，几乎把州城洗劫一空才离去。第二年，贼人又攻打永州、攻破邵州，却没有进犯道州的边境就退走了。这难道是道州的力量能够制服敌人吗？不过是蒙受他们的怜悯罢了。那些使者为什么忍心苦苦征收赋税，因此写诗一篇给官吏们看。
INSERT INTO `corpus_texts` (`book_id`, `pos`, `title`, `sid`, `text`, `translation`, `translation_src`) VALUES
  ('tangshi300', 89, '新嫁娘', 'tangshi-ts-240', '三日入厨下洗手作羹汤未谙姑食性先遣小姑尝', '婚后三天走进厨房，洗净手做羹汤。不知道婆婆的口味，先让小姑尝一尝。', 'public-domain'),
  ('tangshi300', 90, '行宫', 'tangshi-ts-243', '寥落古行宫宫花寂寞红白头宫女在闲坐说玄宗', '寥落的古老行宫，宫中的花寂寞地红着。白头宫女还在这里，闲坐谈论着玄宗。', 'public-domain'),
  ('tangshi300', 91, '玉台体', 'tangshi-ts-241', '昨夜裙带解今朝蟢子飞铅华不可弃莫是藁砧归', '昨夜裙带自己解开，今早蟢子飞来。脂粉不可弃置不用，莫不是丈夫要回来了。', 'public-domain'),
  ('tangshi300', 92, '山石', 'tangshi-ts-53', '山石荦确行径微黄昏到寺蝙蝠飞升堂坐阶新雨足芭蕉叶大栀子肥僧言古壁佛画好以火来照所见稀铺床拂席置羹饭疏粝亦足饱我饥夜深静卧百虫绝清月出岭光入扉天明独去无道路出入高下穷烟霏山红涧碧纷烂漫时见松枥皆十围当流赤足踏涧石水声激激风吹衣人生如此自可乐岂必局束为人鞿嗟哉吾党二三子安得至老不更归', '山石险峻不平，山路狭窄，黄昏时到寺里，蝙蝠飞来飞去。登上殿堂坐在台阶上，刚下过透雨，芭蕉叶肥大、栀子花饱满。僧人说起古壁上佛画很好，举着火来照，看得却不很清楚。铺床扫席摆上饭菜，粗茶淡饭也足以充饥。夜深静静躺卧，各种虫声都停了，清月从山岭升起，月光照进门扉。天明独自离去，没有现成的道路，高高低低地穿行在烟雾之中。山花红艳、涧水碧绿，色彩纷繁烂漫，时时见到松树枥树都有十围粗。对着溪流赤足踏着涧石，水声激荡，风吹动衣裳。人生像这样本来就可乐，何必受拘束被人牵制。唉，我们这几个同道，怎能到老还不归隐呢。', 'public-domain'),
  ('tangshi300', 93, '八月十五夜赠张功曹', 'tangshi-ts-54', '纤云四卷天无河清风吹空月舒波沙平水息声影绝一杯相属君当歌君歌声酸辞且苦不能听终泪如雨洞庭连天九疑高蛟龙出没猩鼯号十生九死到官所幽居默默如藏逃下床畏蛇食畏药海气湿蛰熏腥臊昨者州前捶大鼓嗣皇继圣登夔皋赦书一日行万里罪从大辟皆除死迁者追回流者还涤瑕荡垢清朝班州家申名使家抑坎轲只得移荆蛮判司卑官不堪说未免捶楚尘埃间同时辈流多上道天路幽险难追攀君歌且休听我歌我歌今与君殊科一年明月今宵多人生由命非由他有酒不饮奈明何', '薄云四处消散，天上不见了银河，清风吹过天空，月亮散出波光。沙岸平旷、水面平静，声影都断绝了，我敬你一杯酒，你该唱首歌。你的歌声酸楚、言辞悲苦，我还没听完就泪如雨下。洞庭湖连天，九疑山高耸，蛟龙出没，猩猩和飞鼠哀号。你九死一生才到任所，幽居默默像躲藏的逃犯。下床怕蛇，吃饭怕毒，海气潮湿，蛰虫熏出腥臊之气。昨天州衙前擂响大鼓，新皇继位，起用夔、皋那样的贤臣。赦书一天传行万里，犯死罪的都免去死罪。被贬的追回、流放的放还，洗清污垢、整顿朝班。可州里申报了名字，却被观察使压下，命运坎坷，只调移到荆蛮之地。判司这样的卑官不值一提，免不了在尘埃中被鞭打。同时被贬的人大多已上路，可通向朝廷的天路幽险难以攀登。你别唱了，听我唱，我的歌今天与你不同调。一年中的明月今夜最圆最多，人生由命、不由别的，有酒不喝，怎么对得起这明月呢。', 'public-domain'),
  ('tangshi300', 94, '谒衡岳庙遂宿岳寺题门楼', 'tangshi-ts-55', '五岳祭秩皆三公四方环镇嵩当中火维地荒足妖怪天假神柄专其雄喷云泄雾藏半腹虽有绝顶谁能穷我来正逢秋雨节阴气晦昧无清风潜心默祷若有应岂非正直能感通须臾静扫众峰出仰见突兀撑青空紫盖连延接天柱石廪腾掷堆祝融森然魄动下马拜松柏一径趋灵宫粉墙丹柱动光彩鬼物图画填青红升阶伛偻荐脯酒欲以菲薄明其衷庙令老人识神意睢盱侦伺能鞠躬手持杯珓导我掷云此最吉余难同窜逐蛮荒幸不死衣食才足甘长终侯王将相望久绝神纵欲福难为功夜投佛寺上高阁星月掩映云朣胧猿鸣钟动不知曙杲杲寒日生于东', '五岳的祭祀规格都等同于三公，四方各有山镇环绕，嵩山居中。南方属火、土地荒僻多有妖怪，上天借给神明权柄让他专擅雄威。衡山喷云吐雾、云雾藏住半山腰，虽有绝顶又有谁能登到尽头。我来时正逢秋雨时节，阴气晦暗没有清风。我潜心默默祈祷，仿佛有应验，难道不是正直之心能够感通神明吗。不一会儿阴云静扫、群峰露出，抬头看见山峰突兀地撑着青天。紫盖峰连绵接着天柱峰，石廪峰腾跃堆叠连着祝融峰。景象森然令人心惊，我下马而拜，沿着松柏夹道的小路走向神庙。粉墙红柱光彩闪动，鬼神图画涂着青红之色。我登阶弯腰献上干肉和酒，想用微薄的祭品表明诚心。庙里的老人懂得神意，瞪着眼察言观色、善于鞠躬。他手持杯珓引导我投掷，说这一卦最吉，别的难以相比。我被贬逐到蛮荒之地侥幸不死，衣食刚够便甘愿在此终老。封侯拜相已不抱指望，神明纵然想赐福也难以奏效。夜里投宿佛寺登上高阁，星月在朦胧的云中掩映。猿鸣钟响不知不觉天已破晓，明亮的寒日从东方升起。', 'public-domain'),
  ('tangshi300', 95, '石鼓歌', 'tangshi-ts-56', '张生手持石鼓文劝我试作石鼓歌少陵无人谪仙死才薄将奈石鼓何周纲陵迟四海沸宣王愤起挥天戈大开明堂受朝贺诸侯剑佩鸣相磨蒐于岐阳骋雄俊万里禽兽皆遮罗镌功勒成告万世凿石作鼓隳嵯峨从臣才艺咸第一拣选撰刻留山阿雨淋日炙野火燎鬼物守护烦撝呵公从何处得纸本毫发尽备无差讹辞严义密读难晓字体不类隶与科年深岂免有缺画快剑斫断生蛟鼍鸾翔凤翥众仙下珊瑚碧树交枝柯金绳铁索锁钮壮古鼎跃水龙腾梭陋儒编诗不收入二雅褊迫无委蛇孔子西行不到秦掎摭星宿遗羲娥嗟余好古生苦晚对此涕泪双滂沱忆昔初蒙博士征其年始改称元和故人从军在右辅为我度量掘臼科濯冠沐浴告祭酒如此至宝存岂多毡包席裹可立致十鼓只载数骆驼荐诸太庙比郜鼎光价岂止百倍过圣恩若许留太学诸生讲解得切磋观经鸿都尚填咽坐见举国来奔波剜苔剔藓露节角安置妥帖平不颇大厦深檐与盖覆经历久远期无佗中朝大官老于事讵肯感激徒媕娿牧童敲火牛砺角谁复著手为摩挲日销月铄就埋没六年西顾空吟哦羲之俗书趁姿媚数纸尚可博白鹅继周八代争战罢无人收拾理则那方今太平日无事柄任儒术崇丘轲安能以此上论列愿借辩口如悬河石鼓之歌止于此呜呼吾意其蹉跎', '张生手里拿着石鼓文的拓本，劝我试作一首石鼓歌。少陵杜甫已不在，谪仙李白也已死去，我才学浅薄，对这石鼓又能怎么办呢。周朝纲纪衰败、四海沸腾，宣王发愤而起挥动天戈。大开明堂接受朝贺，诸侯的宝剑玉佩叮当作响、互相磨擦。在岐阳打猎驰骋雄俊，万里之内的禽兽都被网罗。要刻功记业昭告万世，凿开山石做成石鼓，削平了嵯峨的山崖。随从之臣才艺都是第一流，挑选他们撰写刻石留在山阿。任凭雨淋日晒、野火烧灼，鬼神守护、频频驱呵。你从哪里得到这纸拓本，毫发都完备、毫无差错。文辞严正、含义细密，读起来难以通晓，字体既不像隶书也不像科斗文。年代久远岂能没有缺笔，像快剑砍断的蛟鼍。又像鸾凤飞翔、众仙下降，珊瑚碧树交错着枝柯。像金绳铁索锁钮般雄壮，像古鼎跃出水面、龙腾如梭。浅陋的儒者编《诗》没有收入，《大雅》《小雅》狭隘局促，没有这般的从容舒展。孔子西行没有到秦国，如同拾取星宿而遗漏了日月。可叹我爱好古物却生得太晚，面对它泪如雨下。回忆当初蒙召为博士，那年才改元为元和。老朋友在右辅从军，替我度量挖掘石鼓的坑穴。我洗净冠、沐浴身体禀告祭酒，这样的至宝留存下来的还能有多少。用毡包席裹立刻可以取来，十只石鼓只需几头骆驼运载。进献太庙与郜鼎相比，光价岂止超过百倍。圣恩如果允许留在太学，诸生讲解还能互相切磋。当年在鸿都门观经尚且拥挤，眼看全国都要为此奔波而来。剜去苔藓、剔净藓苔，露出石鼓的棱角，安置得妥帖平稳、不偏不倚。用大厦深檐把它遮盖，经历久远也可望无事。朝中高官老于处事，怎肯激动感慨，只是唯唯诺诺敷衍。牧童在石上敲火，牛在上面磨角，谁还肯动手去摩挲它。日销月蚀，终将埋没，我在西边回望六年，徒然吟哦。王羲之的俗书追求姿媚，几张纸还能换得白鹅。继周之后八代争战结束，无人收拾，理当如此又能怎样。如今太平无事了，朝廷重用儒术、推崇孔孟。怎能把这些上奏论列，愿借你悬河般的辩才。石鼓之歌到此为止，唉，我的心意恐怕要落空了。', 'public-domain'),
  ('tangshi300', 96, '左迁至蓝关示侄孙湘', 'poems-cz9-12', '一封朝奏九重天夕贬潮州路八千欲为圣明除弊事肯将衰朽惜残年云横秦岭家何在雪拥蓝关马不前知汝远来应有意好收吾骨瘴江边', '早晨我把一封奏章呈给皇帝，傍晚就被贬到八千里外的潮州。我本想替圣明的朝廷革除弊政，怎么能因衰老而吝惜残余的生命！云横在秦岭上，我的家在何处？大雪堵住蓝关，马也停步不前。我知道你远道而来一定是有用意的，正好在瘴江边收殓我的尸骨。', 'school'),
  ('tangshi300', 97, '秋夜曲', 'tangshi-ts-87', '桂魄初生秋露微轻罗已薄未更衣银筝夜久殷勤弄心怯空房不忍归', '月亮初升、秋露微凉，轻薄的罗衣已觉寒冷却还没有换衣。夜深了还在殷勤地弹着银筝，心里害怕那空房、不忍回去。', 'public-domain'),
  ('tangshi300', 98, '晨诣超师院读禅经', 'tangshi-ts-32', '汲井漱寒齿清心拂尘服闲持贝叶书步出东斋读真源了无取妄迹世所逐遗言冀可冥缮性何由熟道人庭宇静苔色连深竹日出雾露余青松如膏沐澹然离言说悟悦心自足', '从井里打水漱一漱寒凉的牙齿，清一清心，拂去衣上的尘土。闲来手持贝叶经书，走出东斋去诵读。真如本源全然无所执取，虚妄的迹象才是世人所追逐的。佛的遗言希望能默默契合，可修治本性又怎能纯熟。道人庭院寂静，苔色连着深深的竹林。太阳出来，雾露还在，青松像刚洗沐过一样。心境淡然，言语道断，悟道之乐使内心自然满足。', 'public-domain'),
  ('tangshi300', 99, '登柳州城楼寄漳汀封连四州刺史', 'tangshi-ts-207', '城上高楼接大荒海天愁思正茫茫惊风乱飐芙蓉水密雨斜侵薜荔墙岭树重遮千里目江流曲似九回肠共来百越文身地犹自音书滞一乡', '城上的高楼连接着荒远之地，海天般的愁思正茫茫无边。狂风胡乱吹动芙蓉池水，密雨斜斜地打湿薜荔墙。岭上的树木重重遮蔽了望远的视线，江流曲折好似九回肠。我们一同来到百越文身之地，却仍然音信阻隔在一方。', 'public-domain'),
  ('tangshi300', 100, '溪居', 'tangshi-ts-33', '久为簪组累幸此南夷谪闲依农圃邻偶似山林客晓耕翻露草夜榜响溪石来往不逢人长歌楚天碧', '长久被官职所牵累，幸而被贬谪到南夷这地方。闲来与农圃为邻，偶然间倒像个山林隐士。清晨耕作，翻动带露的草；夜里撑船，船桨碰响溪中的石头。往来都遇不到人，放声长歌，楚天一片碧蓝。', 'public-domain'),
  ('tangshi300', 101, '江雪', 'poems-xx2-05', '千山鸟飞绝万径人踪灭孤舟蓑笠翁独钓寒江雪', '千山之中鸟儿都飞尽了，条条小路上没有人迹。只有一叶孤舟上披蓑戴笠的老翁，独自在寒冷的江雪中垂钓。', 'school'),
  ('tangshi300', 102, '渔翁', 'tangshi-ts-57', '渔翁夜傍西岩宿晓汲清湘燃楚竹烟销日出不见人欸乃一声山水绿回看天际下中流岩上无心云相逐', '渔翁夜里靠着西岩住宿，清晨汲取清湘的水、烧着楚地的竹。烟消日出却不见人影，只听到一声欸乃，山水一片翠绿。回头看天际，船已驶入中流，山岩上无心的白云相互追逐。', 'public-domain'),
  ('tangshi300', 103, '蜀先主庙', 'tangshi-ts-154', '天地英雄气千秋尚凛然势分三足鼎业复五铢钱得相能开国生儿不象贤凄凉蜀故妓来舞魏宫前', '天地间的英雄气概，千秋之后仍然凛然。势力形成三足鼎立，要恢复汉室的五铢钱。得到贤相能够开国，生了儿子却不像父亲那样贤明。凄凉的蜀国旧日歌妓，被送来在魏宫前歌舞。', 'public-domain'),
  ('tangshi300', 104, '西塞山怀古', 'tangshi-ts-208', '王濬楼船下益州金陵王气黯然收千寻铁锁沉江底一片降幡出石头人世几回伤往事山形依旧枕寒流今逢四海为家日故垒萧萧芦荻秋', '王濬的战船从益州顺流而下，金陵的王气黯然收去。千寻长的铁锁沉入江底，一片投降的旗帜从石头城上举出。人世间几次为往事感伤，山的形状依旧枕着寒流。如今正逢四海一家的日子，旧日的营垒萧萧、芦荻在秋风中摇动。', 'public-domain'),
  ('tangshi300', 105, '乌衣巷', 'tangshi-ts-271', '朱雀桥边野草花乌衣巷口夕阳斜旧时王谢堂前燕飞入寻常百姓家', '朱雀桥边长满野草野花，乌衣巷口夕阳西斜。从前王导谢安家堂前的燕子，如今飞进了普通百姓的家。', 'public-domain'),
  ('tangshi300', 107, '游子吟', 'poems-xx5-12', '慈母手中线游子身上衣临行密密缝意恐迟迟归谁言寸草心报得三春晖', '慈爱的母亲手里拿着针线，为将要远行的儿子缝制衣服。临行前密密地缝了又缝，担心孩子迟迟不能回来。谁说小草一样微薄的心意，能报答得了春天阳光般的恩情？', 'school'),
  ('tangshi300', 111, '渭城曲', 'poems-xx5-23', '渭城朝雨浥轻尘客舍青青柳色新劝君更尽一杯酒西出阳关无故人', '渭城清晨的细雨润湿了轻尘，客舍旁柳色青青，格外鲜亮。劝你再干一杯酒，向西出了阳关就再没有老朋友了。', 'school'),
  ('tangshi300', 113, '感遇·其一', 'tangshi-ts-1', '孤鸿海上来池潢不敢顾侧见双翠鸟巢在三珠树矫矫珍木巅得无金丸惧美服患人指高明逼神恶今我游冥冥弋者何所慕', '一只孤雁从海上飞来，连城池边的水塘也不敢停留回顾。它侧目看见一对翠鸟，把巢筑在珍贵的三珠树上。那对翠鸟高高地立在树梢，难道就不怕弹丸射来吗？华美的衣裳怕人指点，处在高位会招来神明的厌恶。如今我自在地翱翔在辽阔的天空，捕鸟的人又能对我有什么企图呢。', 'public-domain'),
  ('tangshi300', 114, '感遇·其二', 'tangshi-ts-2', '兰叶春葳蕤桂华秋皎洁欣欣此生意自尔为佳节谁知林栖者闻风坐相悦草木有本心何求美人折', '兰草在春天枝叶繁茂，桂花在秋天花白皎洁。它们欣欣向荣地生长，各自成为美好的时节。谁会想到那隐居山林的人，闻到它们的芬芳便心生爱慕。草木散发香气本是出于天性，哪里是为了求得别人来攀折赏识呢。', 'public-domain'),
  ('tangshi300', 117, '没蕃故人', 'tangshi-ts-155', '前年伐月支城下没全师蕃汉断消息死生长别离无人收废帐归马识残旗欲祭疑君在天涯哭此时', '前年讨伐月支，城下全军覆没。蕃汉之间消息断绝，是生是死都是长久的别离。没有人收拾废弃的营帐，归来的军马认识残破的旗帜。想祭奠你又疑心你还活着，天涯之远、此时唯有痛哭。', 'public-domain'),
  ('tangshi300', 118, '遣悲怀·其一', 'tangshi-ts-209', '谢公最小偏怜女自嫁黔娄百事乖顾我无衣搜荩箧泥他沽酒拔金钗野蔬充膳甘长藿落叶添薪仰古槐今日俸钱过十万与君营奠复营斋', '你像谢公最疼爱的小女儿，自从嫁给我这贫士便百事不顺。看我没有衣服穿就翻箱倒柜寻找，缠着你去买酒、你便拔下金钗。用野菜充饥、甘心吃豆叶，靠落叶添柴、仰仗老槐树。如今我的俸钱已超过十万，却只能为你营办祭奠与斋事。', 'public-domain'),
  ('tangshi300', 119, '遣悲怀·其二', 'tangshi-ts-210', '昔日戏言身后意今朝都到眼前来衣裳已施行看尽针线犹存未忍开尚想旧情怜婢仆也曾因梦送钱财诚知此恨人人有贫贱夫妻百事哀', '从前戏言身后的事，如今都到了眼前来。你的衣裳已经施舍出去、眼看就要用尽，针线还留着、我不忍心打开。还念着旧情而怜惜婢仆，也曾因为梦见你而送去钱财。确实知道这种遗恨人人都有，只是贫贱的夫妻事事都令人悲哀。', 'public-domain'),
  ('tangshi300', 120, '遣悲怀·其三', 'tangshi-ts-211', '闲坐悲君亦自悲百年都是几多时邓攸无子寻知命潘岳悼亡犹费词同穴窅冥何所望他生缘会更难期惟将终夜长开眼报答平生未展眉', '闲坐时悲叹你也悲叹自己，百年又有多长时间。邓攸没有儿子、不久便知天命，潘岳悼亡、仍徒然耗费文词。同穴于幽暗黄泉又有什么可望，来生再会的缘分更加难期。只能整夜长睁着眼，报答你平生未曾舒展的眉头。', 'public-domain'),
  ('tangshi300', 122, '卖炭翁', 'poems-cz8-25', '卖炭翁伐薪烧炭南山中满面尘灰烟火色两鬓苍苍十指黑卖炭得钱何所营身上衣裳口中食可怜身上衣正单心忧炭贱愿天寒夜来城外一尺雪晓驾炭车辗冰辙牛困人饥日已高市南门外泥中歇翩翩两骑来是谁黄衣使者白衫儿手把文书口称敕回车叱牛牵向北一车炭千余斤宫使驱将惜不得半匹红纱一丈绫系向牛头充炭直', '有个卖炭的老翁，在南山里砍柴烧炭。他满脸灰尘，显出被烟熏火燎的颜色，两鬓灰白，十个手指也是黑的。卖炭得来的钱做什么用呢？是为了身上穿的衣裳和口中吃的食物。可怜他身上穿的衣服十分单薄，心里却因担心炭贱而希望天更冷些。夜里城外下了一尺厚的雪，清晨他驾着炭车碾过冰冻的车辙。牛累了，人饿了，太阳已经升得很高了，他就在集市南门外的泥地里歇息。那两个轻快地骑着马而来的人是谁？是穿着黄衣的太监和穿着白衫的爪牙。他们手里拿着公文，口里说是奉了皇帝的命令，便掉转车头，吆喝着牛向北赶去。一车炭，有一千多斤，宫使硬要赶走，老翁舍不得也没有办法。他们只把半匹红纱和一丈绫，系在牛头上就充当炭的价钱了。', 'academic'),
  ('tangshi300', 123, '长恨歌', 'tangshi-ts-58', '汉皇重色思倾国御宇多年求不得杨家有女初长成养在深闺人未识天生丽质难自弃一朝选在君王侧回眸一笑百媚生六宫粉黛无颜色春寒赐浴华清池温泉水滑洗凝脂侍儿扶起娇无力始是新承恩泽时云鬓花颜金步摇芙蓉帐暖度春宵春宵苦短日高起从此君王不早朝承欢侍宴无闲暇春从春游夜专夜后宫佳丽三千人三千宠爱在一身金屋妆成娇侍夜玉楼宴罢醉和春姊妹弟兄皆列土可怜光彩生门户遂令天下父母心不重生男重生女骊宫高处入青云仙乐风飘处处闻缓歌慢舞凝丝竹尽日君王看不足渔阳鼙鼓动地来惊破霓裳羽衣曲九重城阙烟尘生千乘万骑西南行翠华摇摇行复止西出都门百余里六军不发无奈何宛转蛾眉马前死花钿委地无人收翠翘金雀玉搔头君王掩面救不得回看血泪相和流黄埃散漫风萧索云栈萦纡登剑阁峨嵋山下少人行旌旗无光日色薄蜀江水碧蜀山青圣主朝朝暮暮情行宫见月伤心色夜雨闻铃肠断声天旋日转回龙驭到此踌躇不能去马嵬坡下泥土中不见玉颜空死处君臣相顾尽沾衣东望都门信马归归来池苑皆依旧太液芙蓉未央柳芙蓉如面柳如眉对此如何不泪垂春风桃李花开日秋雨梧桐叶落时西宫南内多秋草落叶满阶红不扫梨园弟子白发新椒房阿监青娥老夕殿萤飞思悄然孤灯挑尽未成眠迟迟钟鼓初长夜耿耿星河欲曙天鸳鸯瓦冷霜华重翡翠衾寒谁与共悠悠生死别经年魂魄不曾来入梦临邛道士鸿都客能以精诚致魂魄为感君王辗转思遂教方士殷勤觅排空驭气奔如电升天入地求之遍上穷碧落下黄泉两处茫茫皆不见忽闻海上有仙山山在虚无缥缈间楼阁玲珑五云起其中绰约多仙子中有一人字太真雪肤花貌参差是金阙西厢叩玉扃转教小玉报双成闻道汉家天子使九华帐里梦魂惊揽衣推枕起徘徊珠箔银屏迤逦开云鬓半偏新睡觉花冠不整下堂来风吹仙袂飘飖举犹似霓裳羽衣舞玉容寂寞泪阑干梨花一枝春带雨含情凝睇谢君王一别音容两渺茫昭阳殿里恩爱绝蓬莱宫中日月长回头下望人寰处不见长安见尘雾惟将旧物表深情钿合金钗寄将去钗留一股合一扇钗擘黄金合分钿但教心似金钿坚天上人间会相见临别殷勤重寄词词中有誓两心知七月七日长生殿夜半无人私语时在天愿作比翼鸟在地愿为连理枝天长地久有时尽此恨绵绵无绝期', '汉皇贪恋美色、想得到倾国倾城的佳人，统治天下多年却求之不得。杨家有个女儿刚刚长大成人，养在深闺中无人知晓。天生的美丽资质难以自弃，一朝被选到君王身边。回头一笑就生出百般妩媚，六宫的妃嫔都黯然失色。春寒时赐她在华清池沐浴，温泉水滑，洗涤着她的肌肤。侍女扶起她时娇弱无力，这正是刚承恩泽的时候。鬓发如云、容颜如花、戴着金步摇，芙蓉帐里暖意融融地度过春宵。春宵苦于太短，日头高高升起，从此君王不再提早上朝。承受欢宠、侍奉宴饮没有空闲，春天随着出游，夜里独享君恩。后宫里美貌的佳丽有三千人，三千宠爱都集中在她一人身上。金屋里梳妆完毕娇娇地侍夜，玉楼宴会散后醉意与春意融合。她的姐妹兄弟都封土赐爵，门户上生出无限光彩。于是使天下做父母的心，不看重生男而看重生女。骊山行宫高高直入青云，仙乐随风飘荡处处可闻。缓歌慢舞与丝竹凝合，君王整日看也看不够。渔阳的鼙鼓震地而来，惊破了《霓裳羽衣曲》。九重城阙升起烟尘，千乘万骑向西南而行。翠羽华盖飘飘摇摇走着又停下，西出都门一百多里。六军不肯进发无可奈何，宛转娥眉死在马前。花钿丢在地上无人收拾，还有翠翘、金雀、玉搔头。君王掩面却救不了她，回头望去血泪交相流淌。黄尘散漫、风声萧索，沿着萦回的栈道登上剑阁。峨嵋山下行人稀少，旌旗没有光彩、日色淡薄。蜀江水碧绿、蜀山青翠，圣主朝朝暮暮满怀思念。在行宫里见月是伤心的颜色，夜雨里听铃是断肠的声音。天旋地转，圣驾回京，到此处踌躇着不忍离去。马嵬坡下的泥土中，不见玉颜，只留着她死去的地方。君臣相顾，泪湿衣襟，向东望着都门，信马而回。回京后池苑都依旧，太液池的芙蓉、未央宫的柳树。芙蓉像她的面容、柳叶像她的眉，面对这些怎么能不落泪。春风里桃李花开的日子，秋雨中梧桐叶落的时候。西宫南内长满秋草，落叶满阶、红色无人打扫。梨园弟子新添了白发，椒房的阿监、宫女都已衰老。傍晚殿中流萤飞过，思念悄然，孤灯挑尽也睡不着。钟鼓迟迟，夜刚开始变长，星河明亮将要天亮。鸳鸯瓦冷、霜花厚重，翡翠被寒，有谁与我共眠。悠悠生死一别已经一年，魂魄不曾进入我的梦中。临邛的道士是鸿都的客人，能以精诚招来魂魄。因为感念君王辗转思念，便叫方士殷勤地寻找。排开长空、驾着云气，奔走如电，升天入地寻遍。上穷碧落下至黄泉，两处茫茫都不见踪影。忽然听说海上有座仙山，山在虚无缥缈之间。楼阁玲珑，五色祥云升起，其中有许多绰约的仙子。其中有一位名叫太真，雪白肌肤、如花容貌，大约就是她。在仙宫金阙西厢轻叩玉门，转叫小玉去通报双成。听说汉家天子的使者到来，九华帐里梦魂惊动。她揽衣推枕起身徘徊，珠帘银屏一道道打开。云鬓半偏、刚睡醒的样子，花冠不整地走下堂来。清风吹动仙袖飘飘高扬，还像当年《霓裳羽衣舞》的样子。玉容寂寞、泪痕纵横，像一枝梨花带着春雨。她含情凝视、拜谢君王，一别之后音容两处渺茫。昭阳殿里的恩爱已经断绝，蓬莱宫中的日月却很漫长。回头向下望人间，看不见长安只见尘雾。只能拿旧物来表明深情，把钿盒金钗寄送回去。钗留一股、盒留一扇，把金钗掰开、把钿盒分半。只要心像金钿一样坚贞，天上人间总会相见。临别时殷勤地再三寄语，话中的誓言两心相知。七月七日长生殿，夜半无人私语的时候。在天愿作比翼鸟，在地愿为连理枝。天长地久也有尽时，这绵绵的遗恨却永无绝期。', 'public-domain'),
  ('tangshi300', 124, '琵琶行·并序', 'tangshi-ts-59', '元和十年予左迁九江郡司马明年秋送客湓浦口闻舟中夜弹琵琶者听其音铮铮然有京都声问其人本长安倡女尝学琵琶于穆曹二善才年长色衰委身为贾人妇遂命酒使快弹数曲曲罢悯然自叙少小时欢乐事今漂沦憔悴转徙于江湖间予出官二年恬然自安感斯人言是夕始觉有迁谪意因为长句歌以赠之凡六百一十二言命曰琵琶行浔阳江头夜送客枫叶荻花秋瑟瑟主人下马客在船举酒欲饮无管弦醉不成欢惨将别别时茫茫江浸月忽闻水上琵琶声主人忘归客不发寻声暗问弹者谁琵琶声停欲语迟移船相近邀相见添酒回灯重开宴千呼万唤始出来犹抱琵琶半遮面转轴拨弦三两声未成曲调先有情弦弦掩抑声声思似诉平生不得志低眉信手续续弹说尽心中无限事轻拢慢捻抹复挑初为霓裳后六幺大弦嘈嘈如急雨小弦切切如私语嘈嘈切切错杂弹大珠小珠落玉盘间关莺语花底滑幽咽泉流冰下难冰泉冷涩弦凝绝凝绝不通声渐歇别有幽愁暗恨生此时无声胜有声银瓶乍破水浆迸铁骑突出刀枪鸣曲终收拨当心画四弦一声如裂帛东船西舫悄无言唯见江心秋月白沉吟放拨插弦中整顿衣裳起敛容自言本是京城女家在虾蟆陵下住十三学得琵琶成名属教坊第一部曲罢曾教善才服妆成每被秋娘妒五陵年少争缠头一曲红绡不知数钿头银篦击节碎血色罗裙翻酒污今年欢笑复明年秋月春风等闲度弟走从军阿姨死暮去朝来颜色故门前冷落鞍马稀老大嫁作商人妇商人重利轻别离前月浮梁买茶去去来江口守空船绕船月明江水寒夜深忽梦少年事梦啼妆泪红阑干我闻琵琶已叹息又闻此语重唧唧同是天涯沦落人相逢何必曾相识我从去年辞帝京谪居卧病浔阳城浔阳地僻无音乐终岁不闻丝竹声住近湓江地低湿黄芦苦竹绕宅生其间旦暮闻何物杜鹃啼血猿哀鸣春江花朝秋月夜往往取酒还独倾岂无山歌与村笛呕哑嘲哳难为听今夜闻君琵琶语如听仙乐耳暂明莫辞更坐弹一曲为君翻作琵琶行感我此言良久立却坐促弦弦转急凄凄不似向前声满座重闻皆掩泣座中泣下谁最多江州司马青衫湿', '元和十年，我被贬为九江郡司马。第二年秋天，在湓浦口送客，听见船中夜里有人弹琵琶，听那声音，铮铮然有京城的风味。问那人来历，她本是长安的歌女，曾向穆、曹两位乐师学琵琶，年长色衰，嫁给了商人做妻子。于是我命人摆酒，让她畅快地弹了几曲。弹完她神情悲戚，自述年少时的欢乐往事，如今漂泊憔悴，辗转在江湖之间。我离京外任两年，一向安然自适，听了她的话，这天晚上才感到被贬谪的况味。因而写了这首长句，作歌赠给她，共六百一十二字，题名《琵琶行》。
INSERT INTO `corpus_texts` (`book_id`, `pos`, `title`, `sid`, `text`, `translation`, `translation_src`) VALUES
  ('tangshi300', 139, '题扬州禅智寺', 'tangshi-ts-369', '雨过一蝉噪飘萧松桂秋青苔满阶砌白鸟故迟留暮霭生深树斜阳下小楼谁知竹西路歌吹是扬州', '阵雨过后一只蝉噪鸣，松桂在风里飘动已见秋意。
INSERT INTO `corpus_texts` (`book_id`, `pos`, `title`, `sid`, `text`, `translation`, `translation_src`) VALUES
  ('tangshi300', 181, '寻隐者不遇', 'poems-xx1-10', '松下问童子言师采药去只在此山中云深不知处', '在松树下问小童师父去哪儿了，他说师父采药去了。就在这座山里，云雾深深不知在何处。', 'school'),
  ('tangshi300', 182, '利州南渡', 'tangshi-ts-220', '澹然空水对斜晖曲岛苍茫接翠微波上马嘶看棹去柳边人歇待船归数丛沙草群鸥散万顷江田一鹭飞谁解乘舟寻范蠡五湖烟水独忘机', '空阔的水面淡然对着斜阳，曲折的岛屿苍茫接着青翠的山色。波浪上马在嘶鸣、看船桨划去，柳边有人歇息、等待船回来。几丛沙草、群鸥惊散，万顷江田、一只白鹭飞翔。谁能懂得乘舟去寻访范蠡，在五湖的烟水中独自忘掉机心。', 'public-domain'),
  ('tangshi300', 183, '瑶瑟怨', 'tangshi-ts-289', '冰簟银床梦不成碧天如水夜云轻雁声远过潇湘去十二楼中月自明', '冰凉的竹席、银色的床、梦也做不成，碧天如水、夜云轻淡。雁声远远地越过潇湘而去，十二楼中明月自照。', 'public-domain'),
  ('tangshi300', 184, '送人东游', 'tangshi-ts-165', '荒戍落黄叶浩然离故关高风汉阳渡初日郢门山江上几人在天涯孤棹还何当重相见樽酒慰离颜', '荒凉的戍楼落下黄叶，你意气浩然地离开故关。高风吹过汉阳渡，初日照着郢门山。江上还有几个人，天涯外一只孤舟归去。什么时候才能重见，举杯慰藉这离别的容颜。', 'public-domain'),
  ('tangshi300', 185, '苏武庙', 'tangshi-ts-221', '苏武魂销汉使前古祠高树两茫然云边雁断胡天月陇上羊归塞草烟回日楼台非甲帐去时冠剑是丁年茂陵不见封侯印空向秋波哭逝川', '苏武在汉使面前神魂震撼，古祠与高树都一片茫然。云边的雁影断绝在胡天的月下，陇上的羊群归来在塞草的烟雾中。回来时楼台已经不是当年的甲帐，离去时加冠佩剑正当壮年。汉武帝已看不到他封侯的印绶，只能空对着秋水哀哭逝去的岁月。', 'public-domain'),
  ('tangshi300', 186, '书边事', 'tangshi-ts-168', '调角断清秋征人倚戍楼春风对青冢白日落梁州大漠无兵阻穷边有客游蕃情似此水长愿向南流', '号角声断断续续地响在清秋，征人倚在戍楼上。春风对着青冢，白日落在梁州。大漠上没有兵阻，极远的边地还有客子游历。蕃人的心意就像这河水，但愿长久地向南流。', 'public-domain'),
  ('tangshi300', 187, '贫女', 'tangshi-ts-354', '蓬门未识绮罗香拟托良媒益自伤谁爱风流高格调共怜时世俭梳妆敢将十指夸针巧不把双眉斗画长苦恨年年压金线为他人作嫁衣裳', '生在蓬门小户，从没见识过绮罗的芳香，想托个好媒人，反而更添感伤。
INSERT INTO `corpus_texts` (`book_id`, `pos`, `title`, `sid`, `text`, `translation`, `translation_src`) VALUES
  ('tangshi300', 228, '奉和圣制从蓬莱向兴庆阁道中留春雨中春望之作应制', 'tangshi-ts-180', '渭水自萦秦塞曲黄山旧绕汉宫斜銮舆迥出千门柳阁道回看上苑花云里帝城双凤阙雨中春树万人家为乘阳气行时令不是宸游玩物华', '渭水依旧萦绕着秦地的关塞弯曲而流，黄山依然斜斜地绕着汉宫。天子的车驾远远地出了千门杨柳，在阁道上回头看皇家园林的花。云里帝京耸立着双凤阙，雨中的春树掩映着万户人家。这是顺应阳气来施行时令，不是天子游乐玩赏美景。', 'public-domain'),
  ('tangshi300', 229, '和贾至舍人早朝大明宫之作', 'tangshi-ts-181', '绛帻鸡人报晓筹尚衣方进翠云裘九天阊阖开宫殿万国衣冠拜冕旒日色才临仙掌动香烟欲傍衮龙浮朝罢须裁五色诏佩声归到凤池头', '戴红巾的鸡人报出晓筹，尚衣官刚进上翠云裘。九天的宫门大开，万国的使臣朝拜天子。日色刚照到仙掌、光影闪动，香烟仿佛傍着龙袍浮动。朝罢还要起草五色诏书，玉佩声中回到凤凰池。', 'public-domain'),
  ('tangshi300', 231, '鹿柴', 'poems-xx4-17', '空山不见人但闻人语响返景入深林复照青苔上', '空寂的山里看不见人影，只听见有人说话的声音。落日的余光返照进深林，又映在青苔上。', 'school'),
  ('tangshi300', 232, '竹里馆', 'poems-cz7-14', '独坐幽篁里弹琴复长啸深林人不知明月来相照', '独自坐在幽深的竹林里，一边弹琴一边长声呼啸。深林中没有别人知道，只有明月来与我相伴。', 'academic'),
  ('tangshi300', 234, '相思', 'tangshi-ts-225', '红豆生南国春来发几枝愿君多采撷此物最相思', '红豆生长在南方，春天来时发出几枝。愿你多多采摘，这东西最能寄托相思。', 'public-domain'),
  ('tangshi300', 235, '九月九日忆山东兄弟', 'poems-xx3-16', '独在异乡为异客每逢佳节倍思亲遥知兄弟登高处遍插茱萸少一人', '独自在他乡做客，每到佳节就更加思念亲人。遥想兄弟们登高的地方，插茱萸时唯独少了我一个。', 'school'),
  ('tangshi300', 236, '送崔九', 'tangshi-ts-227', '归山深浅去须尽丘壑美莫学武陵人暂游桃源里', '你归隐山中去、无论深浅，都要尽情领略丘壑的美。不要学那武陵人，只在桃源里短暂一游。', 'public-domain'),
  ('tangshi300', 237, '寻西山隐者不遇', 'tangshi-ts-20', '绝顶一茅茨直上三十里扣关无僮仆窥室唯案几若非巾柴车应是钓秋水差池不相见黾勉空仰止草色新雨中松声晚窗里及兹契幽绝自足荡心耳虽无宾主意颇得清净理兴尽方下山何必待之子', '高高的山顶上有一间茅屋，一直往上要走三十里。敲门却没有童仆应答，窥看屋内只有几案。主人若不是驾着柴车外出，就该是在秋水里垂钓。阴差阳错没能相见，徒然辛劳地仰慕他。新雨过后草色青青，傍晚的窗外传来松涛声。置身这幽绝的境地，已足以涤荡我的心胸与耳目。虽然没有宾主酬答的情意，却也颇得清净的道理。兴致尽了便下山去，何必一定要等到见到他呢。', 'public-domain'),
  ('tangshi300', 238, '黄鹤楼', 'poems-cz8-06', '昔人已乘黄鹤去此地空余黄鹤楼黄鹤一去不复返白云千载空悠悠晴川历历汉阳树芳草萋萋鹦鹉洲日暮乡关何处是烟波江上使人愁', '传说中的仙人已经乘着黄鹤飞走了，这个地方只留下空空的黄鹤楼。黄鹤一去再也没有回来，千百年来只有白云在空中飘飘荡荡。晴日里，汉阳的树木清晰可数，鹦鹉洲上芳草长得十分茂盛。天色已晚，故乡在什么地方呢？江上的烟波使人愁绪满怀。', 'academic'),
  ('tangshi300', 239, '行经华阴', 'tangshi-ts-174', '岧峣太华俯咸京天外三峰削不成武帝祠前云欲散仙人掌上雨初晴河山北枕秦关险驿路西连汉畤平借问路旁名利客何如此处学长生', '高峻的太华山俯视着咸阳，天外的三峰像是刀削不成。武帝祠前的云将要散去，仙人掌峰上的雨刚刚转晴。山河北枕秦关之险，驿路西连着平坦的汉畤。请问路旁追逐名利的人，何不像这样在这里学长生之道。', 'public-domain'),
  ('tangshi300', 240, '望蓟门', 'tangshi-ts-175', '燕台一去客心惊笳鼓喧喧汉将营万里寒光生积雪三边曙色动危旌沙场烽火侵胡月海畔云山拥蓟城少小虽非投笔吏论功还欲请长缨', '一到燕台客子便心惊，笳鼓喧闹的是汉将的军营。万里寒光从积雪中生出，三边的曙光使高悬的旌旗飘动。沙场的烽火侵扰着胡地的月亮，海边的云山簇拥着蓟城。我年少时虽不是投笔从戎的班超，论功却还想请缨杀敌。', 'public-domain'),
  ('tangshi300', 241, '终南望余雪', 'tangshi-ts-228', '终南阴岭秀积雪浮云端林表明霁色城中增暮寒', '终南山北面的山岭秀丽，积雪浮在云端。树林梢头露出晴后的天色，城中更添傍晚的寒意。', 'public-domain'),
  ('tangshi300', 242, '古从军行', 'tangshi-ts-73', '白日登山望烽火黄昏饮马傍交河行人刁斗风沙暗公主琵琶幽怨多野云万里无城郭雨雪纷纷连大漠胡雁哀鸣夜夜飞胡儿眼泪双双落闻道玉门犹被遮应将性命逐轻车年年战骨埋荒外空见蒲桃入汉家', '白天登山瞭望烽火，黄昏在交河边饮马。行人打着刁斗，风沙昏暗，公主的琵琶声里幽怨很多。野云万里不见城郭，雨雪纷纷连接着大漠。胡雁哀鸣夜夜飞翔，胡儿的眼泪双双落下。听说玉门关还被遮断，只能拼着性命跟随轻车将军。年年战死的尸骨埋在荒外，只看见葡萄传入了汉家。', 'public-domain'),
  ('tangshi300', 243, '琴歌', 'tangshi-ts-35', '主人有酒欢今夕请奏鸣琴广陵客月照城头乌半飞霜凄万树风入衣铜炉华烛烛增辉初弹渌水后楚妃一声已动物皆静四座无言星欲稀清淮奉使千余里敢告云山从此始', '主人备酒，今夜欢聚，请来善弹琴的广陵客为我奏一曲。月光照着城头，乌鸦半飞；霜气凄冷万树，寒风吹入衣裳。铜炉香料、华美蜡烛使烛光更亮，先弹《渌水》，后弹《楚妃》。琴声一起，万物都静了下来，满座无言，直到天将亮、星星稀疏。我奉命出使清淮，路远千里，从此要辞别云山开始了。', 'public-domain'),
  ('tangshi300', 244, '送陈章甫', 'tangshi-ts-37', '四月南风大麦黄枣花未落桐叶长青山朝别暮还见嘶马出门思旧乡陈侯立身何坦荡虬须虎眉仍大颡腹中贮书一万卷不肯低头在草莽东门酤酒饮我曹心轻万事如鸿毛醉卧不知白日暮有时空望孤云高长河浪头连天黑津吏停舟渡不得郑国游人未及家洛阳行子空叹息闻道故林相识多罢官昨日今如何', '四月南风吹来大麦金黄，枣花未落桐叶已长。青山早晨一别傍晚又见，马嘶着走出家门便思念故乡。陈侯为人何等坦荡，胡须卷曲、眉毛如虎、额头宽阔。腹中藏着一万卷书，却不肯低头埋没在草野之中。他在东门买酒请我们喝，心里把万事看得轻如鸿毛。醉卧时不知白日已暮，有时空自遥望孤云高飞。长河浪头连天昏黑，渡口官吏停船不能渡。郑国的游子还没到家，洛阳的行人徒然叹息。听说故乡旧识很多，你昨日罢官，如今他们会怎样待你呢。', 'public-domain'),
  ('tangshi300', 245, '听安万善吹觱篥歌', 'tangshi-ts-38', '南山截竹为觱篥此乐本自龟兹出流传汉地曲转奇凉州胡人为我吹傍邻闻者多叹息远客思乡皆泪垂世人解听不解赏长飙风中自来往枯桑老柏寒飕飗九雏鸣凤乱啾啾龙吟虎啸一时发万籁百泉相与秋忽然更作渔阳掺黄云萧条白日暗变调如闻杨柳春上林繁花照眼新岁夜高堂列明烛美酒一杯声一曲', '从南山截下竹子做成觱篥，这种乐器本出自龟兹。流传到汉地曲调变得更加奇妙，凉州的胡人为我吹奏。旁边的邻人听了都叹息，远方的旅客思念家乡都流下泪来。世人只懂得听却不懂得欣赏，乐声像长风在风中自来自往。像枯桑老柏在寒风里飕飗作响，又像九只雏凤鸣叫，细细啾啾。忽然如龙吟虎啸一齐迸发，又像万种声响与百道泉流共奏秋声。忽然又转为《渔阳掺》的曲调，黄云萧条，白日昏暗。变调时仿佛听到杨柳迎春，上林苑繁花照眼一新。除夕之夜高堂上点起明烛，美酒一杯、乐曲一支。', 'public-domain'),
  ('tangshi300', 246, '古意', 'tangshi-ts-36', '男儿事长征少小幽燕客赌胜马蹄下由来轻七尺杀人莫敢前须如猬毛磔黄云陇底白云飞未得报恩不能归辽东小妇年十五惯弹琵琶解歌舞今为羌笛出塞声使我三军泪如雨', '男儿当兵去远征，从小是幽燕一带的健儿。在马蹄下争夺胜负，向来把性命看得轻。杀人时勇猛没人敢上前，胡须像刺猬毛一样张开。陇山下黄云弥漫，白云飞卷，未报答国恩就不能回家。辽东有个十五岁的小妇，惯于弹琵琶、善歌舞。如今她用羌笛吹起出塞的曲调，使我们三军将士泪如雨下。', 'public-domain'),
  ('tangshi300', 248, '送魏万之京', 'tangshi-ts-177', '朝闻游子唱离歌昨夜微霜初渡河鸿雁不堪愁里听云山况是客中过关城树色催寒近御苑砧声向晚多莫见长安行乐处空令岁月易蹉跎', '早晨听到你唱起离别的歌，昨夜微霜刚刚渡过黄河。鸿雁的鸣声在愁中不堪听，云山更是在客旅中所经过的。关城的树色催促寒气临近，御苑的砧声到傍晚更多。不要只看见长安是行乐的地方，白白地让岁月蹉跎。', 'public-domain'),
  ('tangshi300', 249, '春泛若耶溪', 'tangshi-ts-21', '幽意无断绝此去随所偶晚风吹行舟花路入溪口际夜转西壑隔山望南斗潭烟飞溶溶林月低向后生事且弥漫愿为持竿叟', '幽居的意趣没有断绝，此番出行随遇而安。晚风吹着行船，沿着花径进入溪口。入夜后船转入西边的山谷，隔着山望见南斗星。潭上雾气溶溶飘飞，林中月影低低地向后移去。人生世事茫茫无边，我愿做个持竿垂钓的老翁。', 'public-domain'),
  ('tangshi300', 251, '同从弟南斋玩月忆山阴崔少府', 'tangshi-ts-19', '高卧南斋时开帷月初吐清辉澹水木演漾在窗户荏苒几盈虚澄澄变今古美人清江畔是夜越吟苦千里其如何微风吹兰杜', '高卧在南斋的时候，拉开帷幕看见月亮刚刚升起。清辉淡淡地洒在水面与树木上，荡漾着映在窗户之间。时光荏苒，月亮几度圆缺，澄澈的月色变换着古今。我所思念的人在清江之畔，今夜他一定在越地苦苦吟咏。相隔千里又能怎样呢，微风吹送着兰草杜若的芳香。', 'public-domain'),
  ('tangshi300', 253, '春宫曲', 'tangshi-ts-257', '昨夜风开露井桃未央前殿月轮高平阳歌舞新承宠帘外春寒赐锦袍', '昨夜春风吹开了露井边的桃花，未央宫前殿月轮高悬。平阳家的歌女新受恩宠，帘外春寒、赐下锦袍。', 'public-domain'),
  ('tangshi300', 256, '闺怨', 'tangshi-ts-256', '闺中少妇不知愁春日凝妆上翠楼忽见陌头杨柳色悔教夫婿觅封侯', '闺中的少妇不知道愁，春日里盛妆登上翠楼。忽然看见路边的杨柳春色，后悔当初让丈夫去求取封侯。', 'public-domain'),
  ('tangshi300', 257, '芙蓉楼送辛渐', 'poems-xx4-20', '寒雨连江夜入吴平明送客楚山孤洛阳亲友如相问一片冰心在玉壶', '寒雨连着江水，夜里来到吴地；天亮送别友人，只余楚山孤零零。洛阳的亲友如果问起我，就说我的心像玉壶里的冰一样纯洁。', 'school'),
  ('tangshi300', 258, '宿王昌龄隐居', 'tangshi-ts-22', '清溪深不测隐处唯孤云松际露微月清光犹为君茅亭宿花影药院滋苔纹余亦谢时去西山鸾鹤群', '清清的溪水深不可测，隐居之处只有一片孤云。松林间露出淡淡的月亮，清朗的月光仿佛还在为你而照。茅亭里停宿着花的影子，种药的院子里滋生了青苔的纹路。我也要辞别时俗而去，到西山与鸾鹤为群。', 'public-domain'),
  ('tangshi300', 259, '听弹琴', 'tangshi-ts-236', '泠泠七弦上静听松风寒古调虽自爱今人多不弹', '冷冷清清的七弦琴上，静静地听出松风般的寒意。古调虽然我自己喜爱，如今的人却多不弹了。', 'public-domain'),
  ('tangshi300', 260, '送上人', 'tangshi-ts-237', '孤云将野鹤岂向人间住莫买沃洲山时人已知处', '孤云伴随野鹤，怎会在人间居住。不要去购买沃洲山，那是时人已经知道的地方。', 'public-domain'),
  ('tangshi300', 261, '送灵澈', 'tangshi-ts-235', '苍苍竹林寺杳杳钟声晚荷笠带斜阳青山独归远', '苍苍的是竹林寺，杳杳的是傍晚的钟声。你背着斗笠、披着斜阳，独自向青山远处归去。', 'public-domain'),
  ('tangshi300', 262, '送李中丞归汉阳别业', 'tangshi-ts-138', '流落征南将曾驱十万师罢归无旧业老去恋明时独立三边静轻生一剑知茫茫江汉上日暮欲何之', '流落江湖的征南将军，曾经统率十万大军。罢官归来没有旧日的产业，年老还眷恋着清明的时代。他独自镇守、三边安宁，舍生忘死只有那一把剑知道。茫茫的江汉之上，日暮时分你要往哪里去。', 'public-domain'),
  ('tangshi300', 263, '秋日登吴公台上寺远眺', 'tangshi-ts-137', '古台摇落后秋日望乡心野寺来人少云峰隔水深夕阳依旧垒寒磬满空林惆怅南朝事长江独至今', '古台草木摇落之后，秋日里生出望乡之心。荒野的寺庙来人很少，云绕的山峰隔着深水。夕阳照着旧日的营垒，清寒的磬声充满空寂的山林。惆怅南朝的往事，只有长江独自流到如今。', 'public-domain'),
  ('tangshi300', 264, '寻南溪常道士', 'tangshi-ts-140', '一路经行处莓苔见屐痕白云依静渚芳草闭闲门过雨看松色随山到水源溪花与禅意相对亦忘言', '一路走过的地方，青苔上还留着足迹。白云依傍着寂静的水洲，芳草掩闭着闲静的柴门。雨后观赏松树的颜色，顺着山势走到水源。溪花与禅意相对，彼此相看都忘了言语。', 'public-domain'),
  ('tangshi300', 265, '饯别王十一南游', 'tangshi-ts-139', '望君烟水阔挥手泪沾巾飞鸟没何处青山空向人长江一帆远落日五湖春谁见汀洲上相思愁白苹', '望着你远入烟水茫茫，挥手之间泪水沾湿手巾。飞鸟消失在哪里，青山空自对着人。长江上一片孤帆远去，落日下五湖正逢春天。谁看见我在汀洲之上，因相思而对着白苹发愁。', 'public-domain'),
  ('tangshi300', 266, '江州重别薛六柳八二员外', 'tangshi-ts-199', '生涯岂料承优诏世事空知学醉歌江上月明胡雁过淮南木落楚山多寄身且喜沧洲近顾影无如白发何今日龙钟人共老愧君犹遣慎风波', '一生哪料承蒙优诏，世事也只空知学着醉歌。江上明月、胡雁飞过，淮南叶落、楚山众多。寄身此地、且喜离水边沧洲很近，自顾身影、对白发无可奈何。如今老态龙钟、大家都已衰老，惭愧你还要派我要小心风波。', 'public-domain'),
  ('tangshi300', 267, '长沙过贾谊宅', 'poems-cz9-11', '三年谪宦此栖迟万古惟留楚客悲秋草独寻人去后寒林空见日斜时汉文有道恩犹薄湘水无情吊岂知寂寂江山摇落处怜君何事到天涯', '贾谊被贬长沙三年，在这里栖身，万古以来只留下楚客的悲哀。秋草之中，我独自寻找他离去后的踪迹，寒冷的树林里只看到夕阳西下。汉文帝虽然贤明，对他的恩遇尚且如此微薄；湘水无情，凭吊贾谊又怎么知道呢？寂寥冷落的江山，草木摇落的时节，可怜你为什么要来到这天涯之地！', 'school'),
  ('tangshi300', 268, '自夏口至鹦鹉洲夕望岳阳寄源中丞', 'tangshi-ts-201', '汀洲无浪复无烟楚客相思益渺然汉口夕阳斜渡鸟洞庭秋水远连天孤城背岭寒吹角独戍临江夜泊船贾谊上书忧汉室长沙谪去古今怜', '汀洲上没有波浪也没有烟雾，楚客的相思更加渺茫。汉口的夕阳斜照渡鸟，洞庭的秋水远远连着天。孤城背靠山岭、寒风中吹起号角，独戍临江、夜里停泊着船只。贾谊上书忧虑汉室，被贬长沙、古今都为之怜惜。', 'public-domain'),
  ('tangshi300', 269, '赋得暮雨送李胄', 'tangshi-ts-145', '楚江微雨里建业暮钟时漠漠帆来重冥冥鸟去迟海门深不见浦树远含滋相送情无限沾襟比散丝', '楚江笼罩在微雨里，正是建业敲响晚钟的时候。江面漠漠、船帆沉重，天色冥冥、鸟儿迟归。海门深远望不见，水边的树木远远含着水汽。相送的情意无穷无尽，泪水沾湿衣襟，比散乱的雨丝还多。', 'public-domain'),
  ('tangshi300', 270, '九日登望仙台呈刘明府', 'tangshi-ts-176', '汉文皇帝有高台此日登临曙色开三晋云山皆北向二陵风雨自东来关门令尹谁能识河上仙翁去不回且欲近寻彭泽宰陶然共醉菊花杯', '汉文皇帝有一座高台，今日登临、曙色开朗。三晋的云山都向北拱卫，二陵的风雨从东边而来。关门的令尹谁能赏识，河上的仙翁一去不回。且就近去寻访彭泽令那样的县令，乐陶陶地一同醉饮菊花酒。', 'public-domain'),
  ('tangshi300', 272, '秋登兰山寄张五', 'tangshi-ts-16', '北山白云里隐者自怡悦相望始登高心随雁飞灭愁因薄暮起兴是清秋发时见归村人沙行渡头歇天边树若荠江畔洲如月何当载酒来共醉重阳节', '北山的白云里，隐居的人自得其乐。为了遥望你我才登上高处，心随着大雁飞去直到看不见。忧愁因傍晚而生，兴致因清秋而发。时时看见回村的人，在沙滩上行走、在渡口歇息。天边的树木细得像荠菜，江边的沙洲弯得像月亮。什么时候你带着酒来，我们一同醉在重阳节。', 'public-domain'),
  ('tangshi300', 273, '夏日南亭怀辛大', 'tangshi-ts-17', '山光忽西落池月渐东上散发乘夕凉开轩卧闲敞荷风送香气竹露滴清响欲取鸣琴弹恨无知音赏感此怀故人中宵劳梦想', '山上的日色忽然向西落下，池上的月亮渐渐从东边升起。我披散开头发乘着傍晚的凉意，打开窗户闲适地躺卧在敞亮的屋中。荷风送来阵阵香气，竹叶上的露水滴落发出清脆的声响。想取出琴来弹奏，可惜没有知音来欣赏。感念于此，怀念起老朋友，半夜里还在梦中苦苦思念。', 'public-domain'),
  ('tangshi300', 274, '宿业师山房期丁大不至', 'tangshi-ts-18', '夕阳度西岭群壑倏已暝松月生夜凉风泉满清听樵人归欲尽烟鸟栖初定之子期宿来孤琴候萝径', '夕阳越过西边的山岭，各条山谷忽然间已经昏暗。松间的月亮带来夜的凉意，风声泉声充满了清幽的听觉。砍柴的人差不多都回家了，暮烟中的鸟儿也刚刚安歇。你约定今晚来过夜，我抱着孤琴在藤萝小径上等候。', 'public-domain'),
  ('tangshi300', 275, '夜归鹿门山歌', 'tangshi-ts-39', '山寺钟鸣昼已昏渔梁渡头争渡喧人随沙岸向江村余亦乘舟归鹿门鹿门月照开烟树忽到庞公栖隐处岩扉松径长寂寥惟有幽人自来去', '山寺钟声响起，白昼已经昏暮，渔梁渡头人们争着渡河，一片喧闹。行人沿着沙岸走向江村，我也乘船回鹿门山。鹿门的月光照着烟雾散开的树林，忽然来到庞公当年隐居的地方。岩洞的门、松间的小路，长年寂寥，只有我这个幽人自来自去。', 'public-domain');
INSERT INTO `corpus_texts` (`book_id`, `pos`, `title`, `sid`, `text`, `translation`, `translation_src`) VALUES
  ('tangshi300', 276, '临洞庭上张丞相', 'poems-cz8-22', '八月湖水平涵虚混太清气蒸云梦泽波撼岳阳城欲济无舟楫端居耻圣明坐观垂钓者徒有羡鱼情', '八月洞庭湖水暴涨，水面与湖岸齐平，湖水与天空浑然一体。水气蒸腾笼罩着云梦大泽，波涛汹涌震动着岳阳城。我想渡过湖去却没有船只，闲居不仕又愧对圣明的时代。只能坐看那些垂钓的人，白白地生出羡慕鱼儿的心情。', 'school'),
  ('tangshi300', 277, '秦中寄远上人', 'tangshi-ts-133', '一丘常欲卧三径苦无资北土非吾愿东林怀我师黄金燃桂尽壮志逐年衰日夕凉风至闻蝉但益悲', '常想在一座小丘上高卧隐居，可苦于没有修筑三径的钱财。北方不是我的心愿，我怀念东林寺的师父。黄金像烧桂一样耗尽，壮志随着年岁衰减。傍晚凉风吹来，听到蝉鸣更添悲伤。', 'public-domain'),
  ('tangshi300', 278, '宿桐庐江寄广陵旧游', 'tangshi-ts-134', '山暝听猿愁沧江急夜流风鸣两岸叶月照一孤舟建德非吾土维扬忆旧游还将两行泪遥寄海西头', '山色昏暗、听着猿啼发愁，青苍的江水夜里湍急地流。风吹响两岸的树叶，月光照着一只孤舟。建德不是我的故乡，我怀念扬州的旧友。只好把两行眼泪，远远地寄到大海的西头。', 'public-domain'),
  ('tangshi300', 279, '早寒江上有怀', 'tangshi-ts-136', '木落雁南度北风江上寒我家襄水曲遥隔楚云端乡泪客中尽孤帆天际看迷津欲有问平海夕漫漫', '树叶飘落、大雁南飞，北风吹得江上寒冷。我的家在襄水的弯曲处，远远隔着楚地的云端。思乡的泪在客旅中流尽，孤帆向天边望去。迷失了渡口想问路，平阔的海面傍晚茫茫无边。', 'public-domain'),
  ('tangshi300', 280, '留别王维', 'tangshi-ts-135', '寂寂竟何待朝朝空自归欲寻芳草去惜与故人违当路谁相假知音世所稀只应守寂寞还掩故园扉', '寂寂无声还等待什么呢，天天白白地归来。想寻找芳草离去，又舍不得与老朋友分别。当权的人谁来帮助我呢，知音在世上很稀少。只该守着寂寞，回去关上故园的门。', 'public-domain'),
  ('tangshi300', 281, '宴梅道士山房', 'tangshi-ts-130', '林卧愁春尽搴帷览物华忽逢青鸟使邀入赤松家金灶初开火仙桃正发花童颜若可驻何惜醉流霞', '高卧林中愁春天将尽，掀开帷幕观赏景物的芳华。忽然遇到青鸟使者，邀我到赤松子家去。金丹灶刚生起火，仙桃正开着花。如果童颜可以留住，何必吝惜醉饮流霞仙酒。', 'public-domain'),
  ('tangshi300', 282, '与诸子登岘山', 'tangshi-ts-129', '人事有代谢往来成古今江山留胜迹我辈复登临水落鱼梁浅天寒梦泽深羊公碑尚在读罢泪沾襟', '人事有新陈代谢，往来之间便成了古今。江山留下名胜古迹，我们又来登临。水落下去鱼梁洲显得浅，天气寒冷云梦泽显得深。羊公碑还在，读完之后泪水沾湿了衣襟。', 'public-domain'),
  ('tangshi300', 283, '过故人庄', 'poems-xx6-17', '故人具鸡黍邀我至田家绿树村边合青山郭外斜开轩面场圃把酒话桑麻待到重阳日还来就菊花', '老友准备了饭菜，邀我到农家做客。绿树环绕着村庄，青山在城郭外斜卧。打开窗子面对谷场菜园，端着酒谈说庄稼。等到重阳节，还要再来赏菊。', 'school'),
  ('tangshi300', 284, '岁暮归南山', 'tangshi-ts-131', '北阙休上书南山归敝庐不才明主弃多病故人疏白发催年老青阳逼岁除永怀愁不寐松月夜窗虚', '不再到北阙去上书，回到南山的旧屋。没有才能被明主弃置，身体多病故人也疏远。白发催人老去，春天逼近岁末。长怀愁绪睡不着，松间月色照着空寂的夜窗。', 'public-domain'),
  ('tangshi300', 286, '春晓', 'poems-xx1-07', '春眠不觉晓处处闻啼鸟夜来风雨声花落知多少', '春天睡得香甜，不知不觉天就亮了，处处听到鸟儿的鸣叫。回想夜里风雨的声音，不知落了多少花。', 'school'),
  ('tangshi300', 287, '宿建德江', 'poems-xx6-01', '移舟泊烟渚日暮客愁新野旷天低树江清月近人', '我把船停靠在烟雾迷蒙的小洲边，日暮时分，旅人的愁绪又添了一层。旷野无边无际，天比树还低；江水清澈，月影仿佛离人更近了。', 'school'),
  ('tangshi300', 288, '将进酒', 'poems-gz11-06', '君不见黄河之水天上来奔流到海不复回君不见高堂明镜悲白发朝如青丝暮成雪人生得意须尽欢莫使金樽空对月天生我材必有用千金散尽还复来烹羊宰牛且为乐会须一饮三百杯岑夫子丹丘生将进酒杯莫停与君歌一曲请君为我倾耳听钟鼓馔玉不足贵但愿长醉不愿醒古来圣贤皆寂寞惟有饮者留其名陈王昔时宴平乐斗酒十千恣欢谑主人何为言少钱径须沽取对君酌五花马千金裘呼儿将出换美酒与尔同销万古愁', '你没有看见吗？黄河之水从天上奔腾而来，滚滚东流入海再也不回还。你没有看见吗？在高堂明镜前悲叹白发，早晨还是满头青丝，傍晚就变成了白雪。人生得意时就应当尽情欢乐，不要让金杯空对着明月。上天生下我这人才一定有用，千金散尽也还会再来。烹羊宰牛暂且尽情享乐，要喝就应当一饮三百杯。岑夫子，丹丘生，快喝酒，不要停下杯子。我为你们唱一首歌，请你们侧耳为我倾听。那些豪华的宴饮不值得珍贵，只愿长醉不愿醒来。自古以来的圣贤都很寂寞，只有善于饮酒的人才留下了名声。陈王曹植当年在平乐观设宴，斗酒万钱，尽情欢乐。主人为什么说钱少呢？只管去买酒来，让我与你们共饮。这名贵的五花马，这价值千金的裘皮衣，叫我的儿子拿出去换成美酒，让我们一同来消解这万古的愁绪！', 'academic'),
  ('tangshi300', 291, '关山月', 'tangshi-ts-63', '明月出天山苍茫云海间长风几万里吹度玉门关汉下白登道胡窥青海湾由来征战地不见有人还戍客望边色思归多苦颜高楼当此夜叹息未应闲', '明月从天山升起，出没在苍茫的云海之间。长风吹过几万里，一直吹过玉门关。汉朝出兵白登道，胡人窥视青海湾。自古以来征战的地方，不见有人生还。守边的将士望着边地的景色，思归的脸上多是苦色。高楼上的妻子在这夜里，叹息声大约也不曾停歇。', 'public-domain'),
  ('tangshi300', 297, '赠孟浩然', 'tangshi-ts-105', '吾爱孟夫子风流天下闻红颜弃轩冕白首卧松云醉月频中圣迷花不事君高山安可仰徒此揖清芬', '我喜爱孟夫子，他的风流潇洒天下闻名。年轻时就抛弃了官爵车马，白头时高卧在松云之间。醉于明月频频称圣，迷恋花草而不去侍奉君王。像高山一样怎么能够仰望，只好在此拱手敬仰他清高的品德。', 'public-domain'),
  ('tangshi300', 298, '庐山谣寄卢侍御虚舟', 'tangshi-ts-40', '我本楚狂人凤歌笑孔丘手持绿玉杖朝别黄鹤楼五岳寻仙不辞远一生好入名山游庐山秀出南斗傍屏风九叠云锦张影落明湖青黛光金阙前开二峰长银河倒挂三石梁香炉瀑布遥相望回崖沓嶂凌苍苍翠影红霞映朝日鸟飞不到吴天长登高壮观天地间大江茫茫去不还黄云万里动风色白波九道流雪山好为庐山谣兴因庐山发闲窥石镜清我心谢公行处苍苔没早服还丹无世情琴心三叠道初成遥见仙人彩云里手把芙蓉朝玉京先期汗漫九垓上愿接卢敖游太清', '我本是楚国的狂人接舆，唱着凤歌嘲笑孔丘。手拿绿玉杖，清晨辞别黄鹤楼。寻访五岳的仙人不怕路远，一生就喜欢到名山去游历。庐山秀丽地耸立在南斗星旁，像九叠屏风张开的云锦，山影落入明净的湖中，泛着青黛色的光。金阙岩前两座山峰长耸，三石梁上瀑布如银河倒挂。香炉峰与瀑布遥遥相望，回环的山崖、层叠的山嶂凌驾于苍茫之上。翠影红霞映着朝阳，鸟儿也飞不到吴地那辽阔的天空。登高远望，天地间景色壮观，大江茫茫东去不回。万里黄云随风变色，九道白波如雪山奔流。我喜爱作这首庐山谣，诗兴因庐山而发。闲来窥看石镜以清我心，谢灵运走过的地方已被苍苔埋没。早服仙丹便无世俗之情，琴心三叠，道行初成。远远望见仙人在彩云里，手把芙蓉朝拜玉京。我预先约好在九天之上相会，愿与你卢敖一同遨游太清。', 'public-domain'),
  ('tangshi300', 299, '梦游天姥吟留别', 'tangshi-ts-41', '海客谈瀛洲烟涛微茫信难求越人语天姥云霞明灭或可睹天姥连天向天横势拔五岳掩赤城天台四万八千丈对此欲倒东南倾我欲因之梦吴越一夜飞度镜湖月湖月照我影送我至剡溪谢公宿处今尚在渌水荡漾清猿啼脚著谢公屐身登青云梯半壁见海日空中闻天鸡千岩万转路不定迷花倚石忽已暝熊咆龙吟殷岩泉栗深林兮惊层巅云青青兮欲雨水澹澹兮生烟列缺霹雳丘峦崩摧洞天石扉訇然中开青冥浩荡不见底日月照耀金银台霓为衣兮风为马云之君兮纷纷而来下虎鼓瑟兮鸾回车仙之人兮列如麻忽魂悸以魄动恍惊起而长嗟惟觉时之枕席失向来之烟霞世间行乐亦如此古来万事东流水别君去兮何时还且放白鹿青崖间须行即骑访名山安能摧眉折腰事权贵使我不得开心颜', '航海的人谈起瀛洲，烟波渺茫实在难以寻求。越地的人说起天姥山，云霞明灭之间或许还能看见。天姥山连着天向天横亘，山势超出五岳，遮蔽了赤城。天台山高四万八千丈，对着它也要向东南倾倒。我想因此梦游吴越，一夜之间飞过月光下的镜湖。湖月照着我的影子，把我送到剡溪。谢灵运当年住宿的地方如今还在，绿水荡漾，清猿啼叫。我脚穿谢公的木屐，身登直上青云的石梯。半山腰看见海上日出，半空中听到天鸡啼鸣。千岩万壑峰回路转，路径不定，迷恋山花倚着石头，忽然天色已暮。熊在咆哮、龙在吟啸，震动岩石与泉水；使深林战栗，令层巅惊骇。云青青的将要下雨，水澹澹的生起烟雾。闪电霹雳，山峦崩裂。仙洞的石门，轰然从中打开。青天浩荡看不到底，日月照耀着金银台。以彩虹为衣、以风为马，云中的神仙纷纷降下。老虎鼓瑟、鸾鸟驾车，仙人们排列得像麻一样多。忽然心惊魄动，恍然惊醒而长声叹息。身边只有醒来时的枕席，失去了刚才的烟霞仙境。世间行乐也当如此，古来万事都如东流之水。告别你离去何时才回来，暂且把白鹿放养在青崖之间，要走时就骑上它去访名山。怎能低眉弯腰去侍奉权贵，使我不能舒心畅意。', 'academic'),
  ('tangshi300', 300, '金陵酒肆留别', 'tangshi-ts-42', '风吹柳花满店香吴姬压酒唤客尝金陵子弟来相送欲行不行各尽觞请君试问东流水别意与之谁短长', '风吹着柳花，满店都是香气，吴地的姑娘压出酒来招呼客人品尝。金陵的子弟们前来相送，要走未走之间各自饮尽杯中的酒。请你问问那向东流去的江水，这离别的深情与它相比谁短谁长。', 'public-domain'),
  ('tangshi300', 301, '送孟浩然之广陵', 'poems-xx4-23', '故人西辞黄鹤楼烟花三月下扬州孤帆远影碧空尽唯见长江天际流', '老朋友在黄鹤楼与我辞别，在柳絮如烟的三月去扬州。孤帆的影子消失在碧空尽头，只见长江向天边流去。', 'school'),
  ('tangshi300', 302, '渡荆门送别', 'poems-cz8-08', '渡远荆门外来从楚国游山随平野尽江入大荒流月下飞天镜云生结海楼仍怜故乡水万里送行舟', '我乘船远渡到荆门之外，来到楚地漫游。山峦随着平坦的原野的出现而渐渐消失，江水奔流进入辽远无际的原野。月亮倒映在水中，像天上飞下来一面明镜；云气升起，结成了海市蜃楼。我还是怜爱故乡的水，它不远万里送我的行舟。', 'school'),
  ('tangshi300', 303, '送友人', 'poems-cz8-27', '青山横北郭白水绕东城此地一为别孤蓬万里征浮云游子意落日故人情挥手自兹去萧萧班马鸣', '青山横亘在城北，白水环绕着城东。我们在这里分别，你像孤单的蓬草随风飘转，踏上万里征程。浮云飘忽不定，正如游子的心意；落日不忍落下，正如故人的情谊。挥手告别，从此离去，只听见马儿萧萧的嘶鸣。', 'academic'),
  ('tangshi300', 304, '宣州谢朓楼饯别校书叔云', 'tangshi-ts-43', '弃我去者昨日之日不可留乱我心者今日之日多烦忧长风万里送秋雁对此可以酣高楼蓬莱文章建安骨中间小谢又清发俱怀逸兴壮思飞欲上青天揽明月抽刀断水水更流举杯消愁愁更愁人生在世不称意明朝散发弄扁舟', '弃我而去的，昨天的时光已不可挽留；扰乱我心的，今天的日子又有许多烦忧。长风万里送走秋雁，面对这样的景色正可以在高楼上痛饮。你的文章有蓬莱阁的气象、建安的风骨，其间谢朓又清新秀发。我们都怀有飘逸的兴致、雄壮的思绪飞扬，想登上青天去揽取明月。抽刀去砍水，水反而流得更急；举杯消愁，愁反而更愁。人生在世既不能称心如意，不如明天就披散头发，泛一叶小舟而去。', 'public-domain'),
  ('tangshi300', 305, '下终南山过斛斯山人宿置酒', 'tangshi-ts-3', '暮从碧山下山月随人归却顾所来径苍苍横翠微相携及田家童稚开荆扉绿竹入幽径青萝拂行衣欢言得所憩美酒聊共挥长歌吟松风曲尽河星稀我醉君复乐陶然共忘机', '傍晚从青山下来，山间的月亮一路随着我归来。回头望望走过的山路，只见苍苍茫茫横着一片青翠的山色。与友人相携来到田家，孩童为我们打开柴门。绿竹夹着幽静的小路，青藤拂过行人的衣裳。欢谈之间找到了歇息的好地方，姑且举杯共饮美酒。放声长歌吟咏松林的风，唱完时天上银河里的星星已经稀疏。我醉了你也高兴，乐陶陶地把世俗的机巧之心全都忘掉。', 'public-domain'),
  ('tangshi300', 306, '登金陵凤凰台', 'tangshi-ts-178', '凤凰台上凤凰游凤去台空江自流吴宫花草埋幽径晋代衣冠成古丘三山半落青天外二水中分白鹭洲总为浮云能蔽日长安不见使人愁', '凤凰台上曾有凤凰来游，凤凰飞去、台子空留、江水自流。吴宫的花草埋没了幽径，晋代的衣冠成了古坟。三山一半落在青天之外，二水被白鹭洲从中分开。总是因为浮云能够遮蔽太阳，望不见长安使人发愁。', 'public-domain'),
  ('tangshi300', 307, '早发白帝城', 'poems-xx3-08', '朝辞白帝彩云间千里江陵一日还两岸猿声啼不住轻舟已过万重山', '清晨告别彩云缭绕的白帝城，千里之外的江陵一天就能到达。两岸猿猴的叫声还没停，轻快的小船已驶过万重山。', 'school'),
  ('tangshi300', 308, '夜泊牛渚怀古', 'tangshi-ts-109', '牛渚西江夜青天无片云登舟望秋月空忆谢将军余亦能高咏斯人不可闻明朝挂帆席枫叶落纷纷', '牛渚的西江之夜，青天没有一片云。我登船遥望秋月，徒然怀念谢尚将军。我也能高声吟咏，只是这样的人已经听不到了。明天早上就扬帆而去，枫叶纷纷落下。', 'public-domain'),
  ('tangshi300', 309, '月下独酌', 'tangshi-ts-4', '花间一壶酒独酌无相亲举杯邀明月对影成三人月既不解饮影徒随我身暂伴月将影行乐须及春我歌月徘徊我舞影零乱醒时同交欢醉后各分散永结无情游相期邈云汉', '花丛中一壶酒，独自饮酒没有亲近的人。举杯邀请明月，对着影子就成了三人。月亮既不懂得饮酒，影子也只是空随我身。姑且伴月与影，行乐要趁春天。我唱歌月亮徘徊，我起舞影子零乱。醒时一同交欢，醉后各自分散。永远结下这无情的交游，相约在遥远的云汉。', 'public-domain'),
  ('tangshi300', 310, '听蜀僧濬弹琴', 'tangshi-ts-108', '蜀僧抱绿绮西下峨嵋峰为我一挥手如听万壑松客心洗流水余响入霜钟不觉碧山暮秋云暗几重', '蜀地的僧人抱着绿绮琴，从西边的峨嵋峰下来。为我挥手一弹，像听到万壑的松涛。客子之心被流水般的琴声洗净，余音融入霜天的钟声。不知不觉碧山已暮，秋云暗了好几重。', 'public-domain'),
  ('tangshi300', 311, '怨情', 'tangshi-ts-232', '美人卷珠帘深坐颦蛾眉但见泪痕湿不知心恨谁', '美人卷起珠帘，久坐皱眉。只见她泪痕沾湿，却不知她心里怨恨的是谁。', 'public-domain'),
  ('tangshi300', 312, '淮上喜会梁州故人', 'tangshi-ts-144', '江汉曾为客相逢每醉还浮云一别后流水十年间欢笑情如旧萧疏鬓已斑何因不归去淮上有秋山', '我曾在江汉一带做客，每次相逢都醉着回去。像浮云一样分别之后，流水般的十年过去了。欢笑的情谊还如旧日，稀疏的鬓发却已斑白。为什么不回去呢，因为淮上有秋山可赏。', 'public-domain'),
  ('tangshi300', 313, '郡斋雨中与诸文士燕集', 'tangshi-ts-25', '兵卫森画戟宴寝凝清香海上风雨至逍遥池阁凉烦疴近消散嘉宾复满堂自惭居处崇未睹斯民康理会是非遣性达形迹忘鲜肥属时禁蔬果幸见尝俯饮一杯酒仰聆金玉章神欢体自轻意欲凌风翔吴中盛文史群彦今汪洋方知大藩地岂曰财赋强', '卫兵林立，画戟森然，宴饮的寝室里凝聚着清雅的香气。海上的风雨袭来，池阁之间逍遥自在、一片清凉。烦闷的疾病近来将要消散，嘉宾又坐满了厅堂。我惭愧自己居处高显，却未能看到百姓安康。道理通了是非就自然排遣，性情通达就连形迹也忘了。荤腥鲜美的食物正逢时禁，好在蔬菜瓜果还能请大家品尝。低头饮一杯酒，抬头聆听金玉般的美文。心神欢畅身体自然轻快，真想凌风飞翔。吴中之地文史兴盛，众多才俊如今济济一堂。这才知道大藩之地，岂止是财物赋税强盛而已。', 'public-domain'),
  ('tangshi300', 314, '初发扬子寄元大校书', 'tangshi-ts-26', '凄凄去亲爱泛泛入烟雾归棹洛阳人残钟广陵树今朝此为别何处还相遇世事波上舟沿洄安得住', '凄凄然地离开亲爱的人，飘飘荡荡驶进烟雾之中。我这是要乘船回洛阳去的人，耳边还萦绕着广陵树影传来的残钟声。今天在这里与你分别，何处才能再相逢。世事就像波涛上的小船，顺流逆流哪里能停得住。', 'public-domain'),
  ('tangshi300', 315, '寄李儋元锡', 'tangshi-ts-203', '去年花里逢君别今日花开又一年世事茫茫难自料春愁黯黯独成眠身多疾病思田里邑有流亡愧俸钱闻道欲来相问讯西楼望月几回圆', '去年花开时与你相逢又分别，今日花开又是一年。世事茫茫难以预料，春愁黯淡、独自成眠。身体多病、思念田园，县里有流亡的百姓、愧领俸钱。听说你要来看望我，我在西楼望月、月已圆了几回。', 'public-domain'),
  ('tangshi300', 316, '寄全椒山中道士', 'tangshi-ts-27', '今朝郡斋冷忽念山中客涧底束荆薪归来煮白石欲持一瓢酒远慰风雨夕落叶满空山何处寻行迹', '今天郡斋里清冷，忽然想起山中修行的朋友。他在山涧底下捆些柴草，回来煮那白色的石头为食。我想带着一瓢酒，远道去慰问这风雨的夜晚。可落叶铺满了空旷的山野，到哪里去寻找他的踪迹呢。', 'public-domain'),
  ('tangshi300', 317, '赋得暮雨送李胄', 'tangshi-ts-145', '楚江微雨里建业暮钟时漠漠帆来重冥冥鸟去迟海门深不见浦树远含滋相送情无限沾襟比散丝', '楚江笼罩在微雨里，正是建业敲响晚钟的时候。江面漠漠、船帆沉重，天色冥冥、鸟儿迟归。海门深远望不见，水边的树木远远含着水汽。相送的情意无穷无尽，泪水沾湿衣襟，比散乱的雨丝还多。', 'public-domain'),
  ('tangshi300', 318, '送杨氏女', 'tangshi-ts-31', '永日方戚戚出行复悠悠女子今有行大江溯轻舟尔辈苦无恃抚念益慈柔幼为长所育两别泣不休对此结中肠义往难复留自小阙内训事姑贻我忧赖兹托令门任恤庶无尤贫俭诚所尚资从岂待周孝恭遵妇道容止顺其猷别离在今晨见尔当何秋居闲始自遣临感忽难收归来视幼女零泪缘缨流', '整天都在悲戚，出行又是那么遥远。女儿今天要出嫁，要逆着大江乘轻舟而去。你们自幼丧母，我抚育思念，更加慈爱温柔。妹妹是你这做姐姐的抚养大的，今朝分别，两人哭个不停。面对此情我心中郁结，可女儿应当出嫁，难以再留。你从小缺少母亲的教诲，侍奉婆婆让我担忧。好在托身到好人家，但愿能受到信任体恤，不致有什么过失。安贫节俭本是我所崇尚的，嫁妆哪里需要置办周全。要孝顺恭敬，遵守为妇之道，仪容举止都要合乎规矩。离别就在今晨，再见你不知是哪个秋天。平日闲暇时还能自我排遣，临到别时这感情忽然难以收住。回来后看着小女儿，眼泪顺着帽带直往下流。', 'public-domain'),
  ('tangshi300', 319, '长安遇冯著', 'tangshi-ts-28', '客从东方来衣上灞陵雨问客何为来采山因买斧冥冥花正开飏飏燕新乳昨别今已春鬓丝生几缕', '客人从东方来，衣上还带着灞陵的雨痕。我问客人为何而来，他说要为开山采薪来买斧头。花在幽暗中正开着，燕子翩翩飞舞，雏燕刚刚育出。上次分别到如今已是春天，你两鬓又添了几缕白发呢。', 'public-domain'),
  ('tangshi300', 320, '夕次盱眙县', 'tangshi-ts-29', '落帆逗淮镇停舫临孤驿浩浩风起波冥冥日沉夕人归山郭暗雁下芦洲白独夜忆秦关听钟未眠客', '落下风帆停泊在淮水边的城镇，停船靠近一座孤零零的驿站。浩浩荡荡的风掀起波浪，天色昏暗太阳沉入暮色。人们回到山边的城郭，暮色四合；大雁飞落芦洲，一片银白。孤独的夜里思念着秦关故土，我是个听着钟声难以入眠的旅人。', 'public-domain'),
  ('tangshi300', 321, '东郊', 'tangshi-ts-30', '吏舍跼终年出郊旷清曙杨柳散和风青山澹吾虑依丛适自憩缘涧还复去微雨霭芳原春鸠鸣何处乐幽心屡止遵事迹犹遽终罢斯结庐慕陶直可庶', '终年在官署里拘束，出到郊外才感到清晨的空旷清朗。杨柳在和风中舒展，青山使我的思虑淡泊下来。依着树丛正好独自歇息，沿着山涧信步又归去。微雨笼罩着芬芳的原野，春鸠在何处鸣叫。我喜爱幽静，屡屡停下脚步，可公务在身行迹还是匆匆。终究要辞官在此结庐而居，仰慕陶渊明大概能够相近。', 'public-domain'),
  ('tangshi300', 322, '滁州西涧', 'poems-xx3-17', '独怜幽草涧边生上有黄鹂深树鸣春潮带雨晚来急野渡无人舟自横', '我独爱涧边幽静的青草，岸上有黄鹂在深树中鸣叫。春潮带着夜雨来得急，荒野渡口无人，小船自在地横着。', 'school'),
  ('tangshi300', 323, '与高适薛据登慈恩寺浮图', 'tangshi-ts-23', '塔势如涌出孤高耸天宫登临出世界磴道盘虚空突兀压神州峥嵘如鬼工四角碍白日七层摩苍穹下窥指高鸟俯听闻惊风连山若波涛奔凑似朝东青槐夹驰道宫馆何玲珑秋色从西来苍然满关中五陵北原上万古青濛濛净理了可悟胜因夙所宗誓将挂冠去觉道资无穷', '塔势如从地下涌出，孤高耸立在天空。登临其上仿佛超脱了尘世，石阶盘旋在半空。高耸挺拔压着神州大地，峥嵘险峻如同鬼斧神工。四角遮住了太阳，七层高塔逼近苍天。往下看去指点高飞的鸟，俯首倾听惊风的声响。相连的群山如同波涛，奔涌而来好似朝东而拜。青槐夹着驰道，宫馆是多么玲珑。秋色从西边而来，苍茫一片布满关中。北原上的五陵，万古以来都是青蒙蒙的。清净的佛理全然可以领悟，胜妙的因缘是我素来所信奉的。我发誓要辞官而去，以觉道为依托，受益无穷。', 'public-domain');
INSERT INTO `corpus_texts` (`book_id`, `pos`, `title`, `sid`, `text`, `translation`, `translation_src`) VALUES
  ('tangshi300', 324, '白雪歌送武判官归京', 'tangshi-ts-46', '北风卷地白草折胡天八月即飞雪忽如一夜春风来千树万树梨花开散入珠帘湿罗幕狐裘不暖锦衾薄将军角弓不得控都护铁衣冷难著瀚海阑干百丈冰愁云惨淡万里凝中军置酒饮归客胡琴琵琶与羌笛纷纷暮雪下辕门风掣红旗冻不翻轮台东门送君去去时雪满天山路山回路转不见君雪上空留马行处', '北风卷地而来，白草都吹折了，塞外八月就飞起雪花。忽然像是一夜之间春风吹来，千树万树梨花盛开。雪花飘进珠帘沾湿罗幕，狐皮袍不暖、锦被也显薄。将军的角弓冻得拉不开，都护的铁甲冷得穿不上。沙漠纵横着百丈坚冰，愁云惨淡凝结万里。中军帐里摆酒饯别归京的客人，奏起胡琴、琵琶和羌笛。傍晚大雪纷纷落在辕门外，风扯着红旗冻得不能飘动。我在轮台东门送你离去，走时雪已铺满天山路。山回路转，看不见你的身影，雪地上只留下马蹄的印迹。', 'public-domain'),
  ('tangshi300', 325, '轮台歌奉送封大夫出师西征', 'tangshi-ts-45', '轮台城头夜吹角轮台城北旄头落羽书昨夜过渠黎单于已在金山西戍楼西望烟尘黑汉兵屯在轮台北上将拥旄西出征平明吹笛大军行四边伐鼓雪海涌三军大呼阴山动虏塞兵气连云屯战场白骨缠草根剑河风急雪片阔沙口石冻马蹄脱亚相勤王甘苦辛誓将报主静边尘古来青史谁不见今见功名胜古人', '轮台城头夜里吹起号角，轮台城北的旄头星坠落。插羽毛的紧急军书昨夜越过渠黎，单于已经到了金山西边。从戍楼上向西望去，烟尘一片昏黑，汉朝兵马驻扎在轮台北面。上将手持旄节向西出征，天刚亮就吹笛出发、大军开拔。四边擂鼓震得雪海翻涌，三军齐声呐喊使阴山动摇。敌营兵气连云屯聚，战场上白骨缠着草根。剑河风急雪片大，沙口石头冻硬，马蹄都冻得脱落。亚相为国勤劳，甘心吃苦，发誓要报答君王、扫清边尘。自古以来青史留名谁没看见，如今你的功名将胜过古人。', 'public-domain'),
  ('tangshi300', 326, '走马川行奉送封大夫出师西征', 'tangshi-ts-44', '君不见走马川行雪海边平沙莽莽黄入天轮台九月风夜吼一川碎石大如斗随风满地石乱走匈奴草黄马正肥金山西见烟尘飞汉家大将西出师将军金甲夜不脱半夜军行戈相拨风头如刀面如割马毛带雪汗气蒸五花连钱旋作冰幕中草檄砚水凝虏骑闻之应胆慑料知短兵不敢接车师西门伫献捷', '你没看见吗，走马川在雪海边奔流，平沙莽莽一直黄到天边。轮台九月夜里狂风怒吼，满川碎石大如斗，随风满地乱滚。匈奴那边草黄马正肥，金山西边望见烟尘飞扬，汉家大将向西出师。将军夜里不解金甲，半夜行军戈矛互相碰撞，风头如刀把脸割得生疼。马毛带着雪，汗气蒸腾，五花马、连钱马转眼就结成冰，营幕中起草檄文，砚水都冻凝了。敌军听说过这些应当心惊胆寒，料想他们不敢短兵相接，我们就在车师西门等着献捷报吧。', 'public-domain'),
  ('tangshi300', 327, '寄左省杜拾遗', 'tangshi-ts-104', '联步趋丹陛分曹限紫微晓随天仗入暮惹御香归白发悲花落青云羡鸟飞圣朝无阙事自觉谏书稀', '我们并肩快步走上红色的台阶，分属不同官署、相隔在紫微省左右。早晨随着天子的仪仗入朝，傍晚沾着御香归来。白发的人悲叹花落，望着青云羡慕鸟飞。圣明的朝廷没有缺失之事，自己觉得进谏的奏书也少了。', 'public-domain'),
  ('tangshi300', 328, '奉和中书舍人贾至早朝大明宫', 'tangshi-ts-185', '银烛朝天紫陌长禁城春色晓苍苍千条弱柳垂青琐百啭流莺绕建章剑佩声随玉墀步衣冠身惹御炉香共沐恩波凤池里朝朝染翰侍君王', '银烛照着上朝的路、紫陌漫长，宫城的春色在晨光中苍苍。千条柔柳垂在宫门两侧，黄莺百啭绕着建章宫。剑佩的响声随着走上玉阶的脚步，衣冠上沾着御炉的香气。我们一同沐浴皇恩在凤凰池里，天天挥毫侍奉君王。', 'public-domain'),
  ('tangshi300', 329, '逢入京使', 'poems-cz7-16', '故园东望路漫漫双袖龙钟泪不干马上相逢无纸笔凭君传语报平安', '向东望着故乡，路途遥远漫长，两只袖子沾满泪水，擦也擦不干。在马上与你相遇，没有纸笔写信，只好请你捎个口信，告诉我的家人我一切平安。', 'school');
INSERT INTO `corpus_gloss` (`book_id`, `pos`, `title`, `gloss`) VALUES
  ('tangshi300', 5, '蜀道难', '[["噫吁嚱","惊叹声，蜀地方言"],["茫然","渺远不清的样子"],["尔来","从那时以来"],["太白","太白山，在今陕西"],["鸟道","只有鸟能飞过的险路"],["地崩山摧","传说五丁开山，山崩地裂"],["天梯石栈","高险的山路与栈道"],["六龙回日","传说日乘车六龙驾，至此也被挡住"],["高标","极高的标志"],["冲波逆折","波涛冲击回旋"],["猿猱","猿猴"],["青泥","岭名，在今陕西略阳"],["盘盘","盘旋曲折的样子"],["扪参历井","手可摸到参星井宿，极言山高"],["胁息","屏住呼吸"],["抚膺","抚摸胸口"],["巉岩","险峻的山岩"],["子规","杜鹃鸟，啼声凄切"],["凋朱颜","使容颜憔悴"],["连峰","连绵的山峰"],["喧豗","喧闹声"],["砯崖","水流冲击山崖"],["万壑雷","千山万谷响如雷鸣"],["剑阁","四川剑门关"],["崔嵬","高峻的样子"],["一夫当关","一人守关，极言险要"],["匪亲","不是亲信"],["狼与豺","喻叛乱的人"],["锦城","成都的别称"],["咨嗟","叹息"]]'),
  ('tangshi300', 7, '玉阶怨', '[["玉阶","玉石砌的台阶"],["白露","秋夜的露水"],["侵罗袜","露水浸湿丝袜"],["却下","退下"],["水晶帘","水晶做的帘子"],["玲珑","空明澄澈的样子"]]'),
  ('tangshi300', 17, '登楼', '[["客心","旅客的心情"],["万方","四方各地"],["玉垒","山名，在今四川都江堰西"],["寇盗","指入侵的吐蕃军队"],["后主","蜀汉后主刘禅"],["梁甫吟","乐府楚调曲名，诸葛亮隐居时好为此吟"],["登临","登高远望"],["锦江","岷江支流，流经成都"],["北极","北极星，喻唐王朝"],["西山寇盗","指吐蕃"],["可怜","可叹"]]'),
  ('tangshi300', 18, '送李少府贬峡中王少府贬长沙', '[["谪居","贬官流放的地方"],["巫峡","长江三峡之一，在今重庆巫山"],["衡阳归雁","传说北雁南飞至衡阳回雁峰而止"],["青枫江","水名，在今湖南长沙"],["白帝城","古城名，在今重庆奉节"],["圣代","对当时朝廷的敬称"],["踌躇","犹豫不前，这里指迟迟不忍分手"]]'),
  ('tangshi300', 19, '望岳', '[["岱宗","泰山的尊称，岱为泰山别称"],["齐鲁","春秋时齐国与鲁国，泛指泰山南北"],["造化","天地大自然"],["钟","聚集"],["阴阳","山的北面与南面"],["决眦","睁大眼睛，眼眶像要裂开"],["会当","终当，定要"]]'),
  ('tangshi300', 20, '兵车行', '[["辚辚","车行时的声响"],["萧萧","马的鸣叫声"],["行人","出征的士兵"],["点行","按名册点名征调"],["里正","古代乡里的小吏"],["戍边","驻守边疆"],["山东","华山以东地区"],["荆杞","荆棘与枸杞，指荒芜"],["县官","官府"],["青海头","青海湖边，古战场"]]'),
  ('tangshi300', 21, '赠卫八处士', '[["参与商","参星与商星此出彼没，喻难以相见"],["苍","灰白"],["访旧","打听故旧亲朋的消息"],["热中肠","内心激动不安"],["父执","父亲的朋友"],["罗酒浆","摆上酒菜"],["黄粱","黄米饭"],["累","接连"],["故意","旧日的情意"]]'),
  ('tangshi300', 22, '丽人行', '[["三月三日","上巳节，古人到水边祓除不祥"],["态浓意远","姿态浓丽而神气高远"],["蹙金","用金线刺绣皱缩成纹"],["翠微盍叶","翠色薄薄的发饰"],["腰衱","裙带"],["椒房亲","皇后亲属，指杨贵妃姐妹"],["紫驼之峰","骆驼峰肉，珍贵食品"],["犀箸","犀牛角做的筷子"],["鸾刀","饰有鸾铃的刀"],["飞鞚","飞奔的马"],["杂遝","众多杂乱"],["要津","显要地位"],["青鸟","传说的神鸟，代指信使"],["炙手可热","手一靠近就烫，喻权势极盛"],["丞相","指杨国忠"]]'),
